const CAT_3={"id":3,"n":"Університет","sub":"Глибоке навчання","e":"🎓","col":"c3","blocks":[{"n":"🔬 БЛОК 1: Наукова діяльність, першоджерела та опрацювання літератури","e":"","cards":[[202,"Пошук у наукових базах даних","<div class=\"rule-note\">🔍 <b>Наукові бази даних</b> — не Google Scholar. Правильний пошук у Scopus, Web of Science, PubMed дає рецензовані статті, а не блоги та реферати.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Ключові бази даних</b><br>Scopus і Web of Science — мультидисциплінарні, платні (є доступ через університети). PubMed — медицина і біологія, безкоштовно. ERIC — педагогіка. SSRN — соціальні науки, препринти безкоштовно.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Оператори пошуку</b><br>AND — звужує: «climate AND education». OR — розширює: «school OR university». NOT — виключає. «\"точна фраза\"» — лапки. Truncati* — зірочка для форм слова.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Фільтри для якісних результатів</b><br>Рік публікації (останні 5–10 років). Peer-reviewed / Рецензовані. Мова. Тип документу (article, review). Відсортуй за цитованістю — популярні статті важливі.</div></div><div class=\"final-note\">📌 Безкоштовні альтернативи: Google Scholar (широко, але менш точно). Semantic Scholar. ResearchGate (можна попросити статтю у автора). Sci-Hub — юридично спірний, але існує.</div>"],[203,"Скринінг наукової статті","<div class=\"rule-note\">📄 <b>Скринінг статті</b> — швидка оцінка: чи варта ця стаття повного читання? У систематичних оглядах більшість знайдених статей відсівається на цьому кроці. Мета: не читати зайвого, не пропустити потрібного.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Крок 1: Назва і анотація</b><br>Відповідає темі? Є конкретні результати? Часовий діапазон і вибірка прийнятні? Якщо ні — не читаєш далі. Не витрачай час на статтю, яка не відповідає твоєму питанню вже на цьому рівні.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Крок 2: Вступ і висновки</b><br>Яка проблема? Яка мета? Що знайдено? Чи відповідає на твоє дослідницьке питання? Часто достатньо прочитати abstract + conclusions, щоб вирішити: потрібна стаття чи ні.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Крок 3: Методологія</b><br>Як зібрані дані? Вибірка репрезентативна? Метод відповідає питанню? Є обмеження? Це вирішує: довіряти результатам чи ні. Слабка методологія = результати ненадійні незалежно від висновків.</div></div><div class=\"final-note\">📌 Правило нелінійного читання: «Анотація → Висновки → Вступ → Методологія → Результати → Обговорення». Не зверху вниз — це ефективніше для скринінгу. Час залежить від складності статті — не прив'язуйся до хвилин.</div>"],[204,"Використання менеджерів цитувань","<div class=\"rule-note\">📚 <b>Менеджери цитувань</b> — Zotero, Mendeley, EndNote. Збирають джерела, форматують бібліографію автоматично. Незамінні при роботі з 20+ джерелами.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Zotero (безкоштовно, рекомендовано)</b><br>Встановлюється як плагін браузера. Одне натискання — зберігає статтю з усіма метаданими. Плагін для Word/Google Docs — вставляє цитату і список літератури одним кліком.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Організація бібліотеки</b><br>Колекції = папки за темами. Теги = ключові слова. Нотатки = твій коментар до статті. Пошук по всій бібліотеці в секунду.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Стилі цитування</b><br>APA, MLA, Chicago, ДСТУ — перемикаєш одним кліком. Автоматично форматує список літератури. Ніколи більше не форматуй вручну.</div></div><div class=\"final-note\">📌 Порада: налаштуй синхронізацію з хмарою. Доступ до бібліотеки з будь-якого пристрою. При написанні диплому/дисертації — незамінний інструмент.</div>"],[205,"Критичний аналіз методології","<div class=\"rule-note\">🔎 <b>Критичний аналіз</b> — не «знайти помилки», а оцінити: наскільки висновки підкріплені даними? Це ключова навичка рецензента і зрілого дослідника.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Питання до вибірки</b><br>Яка вибірка? Репрезентативна для генеральної сукупності? N достатнє? Чи є selection bias (не випадкова вибірка)?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Питання до методу збору даних</b><br>Анкета валідна і надійна? Спостереження об'єктивне? Експеримент контрольований? Чи є confounding variables (приховані чинники)?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Питання до аналізу</b><br>Статистичні тести відповідають типу даних? Є ефект розміру (не лише p-value)? Висновки відповідають даним — чи автори «вийшли за межі»?</div></div><div class=\"final-note\">📌 Корисний фреймворк: CASP (Critical Appraisal Skills Programme) — набір чеклістів для оцінки різних типів досліджень (RCT, якісне, систематичний огляд). Доступний безкоштовно.</div>"],[206,"Виявлення наукового біасу (Bias)","<div class=\"rule-note\">⚖️ <b>Науковий біас</b> — систематичне викривлення результатів. Є у кожному дослідженні. Завдання: виявити і врахувати. Для соціальних і гуманітарних наук особливо критично.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Publication і Confirmation bias</b><br><b>Publication bias</b>: позитивні результати публікуються частіше — звідси мета-аналізи часто завищують ефекти. <b>Confirmation bias</b>: дослідники помічають докази «за» гіпотезу і ігнорують «проти». Перевірка: чи шукав автор докази ПРОТИ своєї теорії?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Sampling, Response і Recall bias</b><br><b>Sampling</b>: вибірка не репрезентативна. <b>Response</b>: анкетують охочих, а не всіх. <b>Recall bias</b>: люди неточно пам'ятають минуле — критично у ретроспективних опитуваннях. Рішення: рандомізована вибірка, контроль відмов, верифікація відповідей.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Hawthorne effect і Demand characteristics</b><br><b>Hawthorne effect</b>: учасники змінюють поведінку, бо знають, що за ними спостерігають. <b>Demand characteristics</b>: учасники здогадуються про мету і відповідають «правильно», а не чесно. Рішення: сліпий дизайн, нейтральні формулювання питань.</div></div><div class=\"final-note\">📌 Replication crisis: більшість гучних психологічних досліджень 2000-х не відтворюється. Правило: один результат — цікаво. Відтворений кількома командами — знання. Вказуй можливі біаси у розділі «Обмеження дослідження».</div>"],[207,"Систематичний літературний огляд","<div class=\"rule-note\">📋 <b>Систематичний огляд</b> — найвищий рівень доказовості. Відрізняється від звичайного огляду: є задокументований протокол пошуку, критерії включення і відтворюваний процес відбору.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>PRISMA і PROSPERO</b><br><b>PRISMA</b>: стандарт звітності (блок-схема: знайдено → відсіяно за назвою → за анотацією → повний текст → включено). <b>PROSPERO</b>: міжнародний реєстр протоколів систематичних оглядів — реєструй протокол ДО початку пошуку, щоб уникнути звинувачень у cherry-picking результатів.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Критерії включення і Cochrane</b><br>Критерії (PICO: Population, Intervention, Comparison, Outcome) визначаються до пошуку. <b>Cochrane Collaboration</b> — провідна міжнародна організація, що публікує систематичні огляди у медицині та охороні здоров'я (cochranelibrary.com). Їхні огляди — золотий стандарт доказової медицини.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мета-аналіз: кількісний синтез</b><br>Мета-аналіз — статистичне об'єднання результатів кількох досліджень в один узагальнений ефект. Дає вищу статистичну потужність, ніж кожне дослідження окремо. Потребує однорідності методів (гетерогенність — окрема проблема, оцінюється через I²).</div></div><div class=\"final-note\">📌 Для курсових і магістерських: не обов'язково повний PRISMA, але варто задокументувати: де шукав, якими запитами, скільки статей переглянув, скільки включив і чому. Це і є мінімальний рівень відтворюваності.</div>"],[208,"Робота з іноземною науковою літературою","<div class=\"rule-note\">🌐 <b>Іноземна наукова література</b> — переважна більшість актуальних публікацій у природничих, технічних і медичних науках виходить англійською. Уникати їх = залишатись у провінційній науці.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Читання наукового англійського</b><br>Academic English — формальний, з шаблонами. Вивчи кліше: «This study aims to…», «The findings suggest that…», «Contrary to previous research…». Вони — навігатори тексту. Читай Abstract + Introduction + Conclusion спочатку — без перекладу.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Переклад і розуміння</b><br>DeepL і Google Translate суттєво покращились — обидва корисні. DeepL часто точніший для гуманітарних і соціальних текстів; для вузькотехнічних або медичних термінів — перевіряй обидва і порівнюй з оригіналом. Перекладай абзацами, не реченнями — контекст важливий. Незнайомий термін: спочатку шукай визначення в тій самій статті.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Цитування іноземних джерел</b><br>Зберігай оригінальний текст. При цитуванні вказуй мову оригіналу або давай переклад у дужках. Переклад назв статей і книг: курсивом у квадратних дужках. Перевір вимоги кафедри: деякі вимагають наводити лише оригінал, інші — з перекладом.</div></div><div class=\"final-note\">📌 Порада: 20–30 статей за спеціальністю — і academic English стає зрозумілим. Не перекладай кожне слово: схопи структуру абзацу → знайди тезу → прочитай деталі. Це вдвічі швидше за послівний переклад.</div>"],[209,"Пошук Research Gaps","<div class=\"rule-note\">🕳️ <b>Research Gap</b> — прогалина в знаннях, яку твоє дослідження закриває. Знайти її = обґрунтувати актуальність науково, а не інтуїтивно. Без чіткої прогалини — немає наукового внеску.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Типи прогалин</b><br>Прогалина знань: феномен ще не вивчено. Методологічна: вивчено лише одним методом. Популяційна: є для дорослих, немає для підлітків. Географічна: є для США, немає для України. Часова: дані застаріли.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>PICO/PECO фреймворк</b><br>Структурує дослідницьке питання і допомагає побачити прогалину. <b>P</b>opulation — кого досліджуємо. <b>I/E</b>ntervention/Exposure — що впливає. <b>C</b>omparison — з чим порівнюємо. <b>O</b>utcome — який результат. Питання «Чи є PICO-дослідження для мого контексту?» і є пошуком прогалини.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як знайти в літературі</b><br>Шукай у висновках статей: «Future research should…», «This study was limited by…», «Little is known about…» — прямі підказки від авторів. Переглянь «Limitations» і «Future Research» розділи 10–15 ключових статей теми.</div></div><div class=\"final-note\">📌 Формулювання: «Незважаючи на значний обсяг досліджень X (посилання), питання Y у контексті Z залишається недостатньо вивченим». Вибирай прогалину, яку можеш закрити своїми реальними ресурсами — часом, доступом до даних, методами.</div>"],[210,"Концептуальна порівняльна матриця","<div class=\"rule-note\">📊 <b>Порівняльна матриця</b> — таблиця, де рядки = джерела, стовпці = ключові параметри. Перетворює стос статей на структурований огляд.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура матриці</b><br>Стовпці: Автор/рік | Мета | Метод | Вибірка | Результати | Обмеження | Відношення до твоєї теми. Заповнюй по одній статті — не намагайся тримати все в голові.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як використовувати</b><br>При написанні огляду: переглянь матрицю → знайди спільні теми → групуй статті → пиши «За даними Петренко (2020) і Коваль (2022)…» замість «Петренко (2020) стверджує, що…»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Визначення суперечностей</b><br>Колонка «Результати» показує, де автори не згодні. Це — найцінніший матеріал для огляду: «Результати суперечливі: X знайшов A, тоді як Y виявив B».</div></div><div class=\"final-note\">💡 Google Sheets або Notion — зручний формат. Матриця з 20–30 статей = готовий скелет теоретичного розділу. Це не підготовка до написання — це вже написання.</div>"],[211,"Верифікація первинних даних","<div class=\"rule-note\">✅ <b>Верифікація даних</b> — перевірка, чи дані є тим, чим здаються. «Брудні» дані дають хибні висновки навіть при правильному аналізі. Це не бюрократія — це умова достовірності результатів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Перевірка на помилки введення</b><br>Екстремальні значення: людина 250 кг, вік −5 років — помилки введення. Пропущені значення: як багато? Випадкові чи систематичні? Дублікати: один респондент двічі? Перевіряй перед будь-яким аналізом.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Перевірка внутрішньої узгодженості</b><br>Відповіді на схожі питання мають корелювати. «Я ніколи не вживаю алкоголь» і «Я п'ю щодня» — суперечність → помилка або брехня. Для анкет: reverse-coded items (навмисно протилежні питання) допомагають виявити неуважних респондентів.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Документування очищення</b><br>Кожна зміна — зафіксована: що змінено, чому, дата. Первинний файл — не чіпай (зберігай окремо). Аналізуй лише очищену копію. Це забезпечує відтворюваність: інший дослідник повторить той самий процес і отримає той самий результат.</div></div><div class=\"final-note\">📌 «Garbage in — garbage out» — основний принцип. У реальних великих проєктах очищення займає значну частину часу. У студентських дослідженнях — менше, але пропускати цей крок не можна: помилка в даних перекреслює весь аналіз.</div>"],[212,"Техніка Deep Reading","<div class=\"rule-note\">📖 <b>Deep Reading</b> — повне критичне читання наукового тексту. Відрізняється від скринінгу: не «що написано», а «чому написано саме так і наскільки це обґрунтовано».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>SQ3R-метод</b><br>Survey (огляд структури) → Question (сформулюй питання до тексту) → Read (читай, шукаючи відповіді) → Recite (перекажи своїми словами) → Review (підсумок і прогалини).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Активне анотування</b><br>Маркер + нотатки на полях (або в PDF-ридері): ! = важливо, ? = незрозуміло, → = зв'язок з іншою ідеєю, ✗ = сумнівно. Після читання — переглянь маркери.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Синтез після читання</b><br>Закрий текст. Запиши: 1) головна теза, 2) три ключових аргументи, 3) моя критика або питання. 10 хвилин — і стаття стала частиною твого знання.</div></div><div class=\"final-note\">💡 Правило Фейнмана для наукових текстів: після читання поясни статтю людині без профільної освіти. Де спотикаєшся — там не зрозумів, а не автор написав незрозуміло.</div>"],[213,"Налаштування наукових сповіщень","<div class=\"rule-note\">🔔 <b>Наукові сповіщення</b> — автоматичне відстеження нових публікацій за твоєю темою. Встановив раз — отримуєш нові статті без повторного пошуку.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Google Scholar Alerts</b><br>scholar.google.com → «Мої сповіщення» → введи ключові слова або назву автора. Лист на email при новій публікації. Безкоштовно.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Scopus і Web of Science</b><br>Збережений пошук + сповіщення. Більш точні результати, ніж Google Scholar. Доступно через університетський акаунт.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>ResearchGate і Academia.edu</b><br>Follow авторів у твоїй галузі. Сповіщення про нові публікації конкретних дослідників. Прямий контакт з авторами — можна попросити статтю.</div></div><div class=\"final-note\">📌 Стратегія: налаштуй 3–5 ключових термінів теми + імена 5–7 провідних авторів галузі. Раз на тиждень — 15 хвилин перегляду нових надходжень. Завжди актуальна бібліографія.</div>"],[214,"Ведення Lab Notebook","<div class=\"rule-note\">🗒️ <b>Лабораторний журнал</b> (Lab Notebook) — хронологічний запис усього, що робиш у дослідженні. Захищає від «я забув, що робив три місяці тому».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що записувати</b><br>Дата і мета кожної сесії роботи. Що зробив. Що отримав (результати, числа, помилки). Питання і наступні кроки. Посилання на файли.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Формат</b><br>Паперовий (нумеровані сторінки, не стираємо — закреслюємо з поясненням) або цифровий (Notion, OneNote, Lab Archives). Ключове: хронологія і конкретика.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Навіщо це потрібно</b><br>Захист від плагіату і суперечок про авторство. Відтворюваність через рік. Матеріал для методологічного розділу. Доказ у разі помилки в даних.</div></div><div class=\"final-note\">📌 Золоте правило: «Якщо не записано — не існує». У науковій практиці необдокументований результат = відсутній результат. Журнал — це твій науковий паспорт.</div>"],[215,"Аналіз патентної інформації","<div class=\"rule-note\">⚙️ <b>Патентний пошук</b> — обов'язковий для технічних і прикладних досліджень. Показує: вирішено чи ні технічне завдання, і ким.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Де шукати патенти</b><br>Google Patents (безкоштовно, зручно). Espacenet (Європейське патентне відомство). Укрпатент (Україна). USPTO (США). WIPO PatentScope (міжнародні).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Що аналізувати в патенті</b><br>Формула (Claims) — юридичний обсяг захисту. Опис (Description) — технічне рішення. Малюнки. Дата пріоритету (не публікації). Статус: чинний/не чинний.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Навіщо в дипломній роботі</b><br>Розділ «Аналіз існуючих рішень» — патенти + наукові статті. Показує актуальність і підтверджує новизну твого рішення. «Відомі рішення мають обмеження X, тому...»</div></div><div class=\"final-note\">💡 Факт: більшість патентів містять детальні технічні описи, яких немає в статтях. Іноді патент — найкраще першоджерело для технічного розділу огляду.</div>"],[216,"Оцінка авторитетності видання","<div class=\"rule-note\">📰 <b>Авторитетність видання</b> — не всі журнали рівні. Публікація в хижацькому журналі шкодить репутації більше, ніж відсутність публікації.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Імпакт-фактор і квартилі</b><br>IF (Impact Factor) — середня кількість цитувань статей журналу. Q1–Q4 (квартилі) за Scopus/WoS. Q1 — топ 25% журналів галузі. Перевірка: Scimago Journal Rankings (SJR).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Ознаки хижацького журналу</b><br>Обіцяє публікацію за 24–48 год. Невідповідний редакційний процес. Запити «Запрошуємо вас опублікувати» без контексту. Перевірка: Think Check Submit (thinkchecksubmit.org); Cabell's Blacklist. Beall's List закрито у 2017 — архів на scholarlyoa.com.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Відкритий доступ (Open Access)</b><br>DOAJ (Directory of Open Access Journals) — реєстр легітимних OA-журналів. Перевіряй перед сплатою APC (Article Processing Charge). Законні OA-журнали мають прозорий рецензійний процес.</div></div><div class=\"final-note\">📌 Правило: спочатку перевір журнал, потім надсилай рукопис. Публікація в поганому журналі або навіть сам запит від такого журналу — сигнал для керівника і рецензентів.</div>"],[217,"Міждисциплінарний синтез","<div class=\"rule-note\">🔀 <b>Міждисциплінарний синтез</b> — поєднання методів і теорій різних дисциплін для вирішення однієї проблеми. Більшість актуальних наукових питань вимагає цього.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Навіщо виходити за межі дисципліни</b><br>Психологічна проблема може потребувати нейробіологічного пояснення. Соціальна — економічного. Технічна — етичного. Монодисциплінарний підхід бачить лише частину реальності.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як будувати синтез</b><br>1. Визнач центральне питання. 2. Знайди, як кожна дисципліна відповідає на нього. 3. Порівняй відповіді. 4. Знайди суперечності. 5. Запропонуй інтегровану відповідь.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Складнощі і рішення</b><br>Різний понятійний апарат: однакові слова, різний зміст. Рішення: явно визначай терміни для кожної дисципліни. Різні методи: обирай ті, що доповнюють один одного.</div></div><div class=\"final-note\">📌 Приклади міждисциплінарних полів: поведінкова економіка (економіка + психологія), нейромаркетинг (нейронауки + маркетинг), педагогічна психологія. Найцікавіша наука — на межах.</div>"],[218,"Анотування PDF-документів","<div class=\"rule-note\">✏️ <b>Анотування PDF</b> — активна робота з текстом замість пасивного читання. Перетворює читання на діалог з автором.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Інструменти</b><br>Adobe Acrobat Reader (безкоштовно) — підсвічування, нотатки, штампи. Zotero — нотатки прив'язані до бібліографії. Hypothes.is — веб-анотації. PDF Expert (iOS).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Система позначок</b><br>Жовте підсвічування = важлива ідея. Зелене = підтверджує мою гіпотезу. Рожеве = суперечить або сумнівно. Нотатки: своє формулювання або питання автору.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Нотатки після читання</b><br>В Zotero або окремому файлі: «Стаття X стверджує Y (с. 45), що суперечить Z (стаття B, с. 23)». Такі нотатки — готові фрагменти огляду літератури.</div></div><div class=\"final-note\">💡 Порада: кольорове кодування за типом інформації, а не за важливістю. Наприклад: синій = методологія, зелений = результати, помаранчевий = моє питання. Однакова система у всіх PDF → швидкий пошук.</div>"],[219,"Семантичні карти проблем (Concept Maps)","<div class=\"rule-note\">🗺️ <b>Концептуальна карта</b> — візуальне відображення зв'язків між ідеями. Допомагає побачити структуру складної проблеми, яку неможливо тримати в голові.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Відмінність від Mind Map</b><br>Mind Map = ієрархія від центру. Concept Map = мережа зв'язків між концептами з підписаними стрілками («викликає», «залежить від», «суперечить»). Concept Map точніший для науки.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як будувати</b><br>1. Виписати всі ключові концепти теми. 2. Розташувати на аркуші. 3. Намалювати стрілки між пов'язаними. 4. Підписати кожну стрілку. 5. Переглянь — чи є прогалини?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Застосування</b><br>Перед написанням теоретичного розділу: карта показує, що де взяти. При читанні нової статті: де вона вписується в твою карту? Для презентації: карта → схема слайду.</div></div><div class=\"final-note\">🛠️ Інструменти: CmapTools (безкоштовно, спеціально для concept maps). Miro. Draw.io. Papір і маркери — швидко і ефективно.</div>"],[220,"Аналіз методологічного апарату","<div class=\"rule-note\">🔬 <b>Методологічний апарат</b> — повний набір: мета, завдання, об'єкт, предмет, гіпотеза, методи. Без нього дослідження — не наука, а «я поспостерігав».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Ієрархія: мета → завдання → методи</b><br>Мета одна. Завдання — підетапи для досягнення мети (3–5). Метод — спосіб виконання конкретного завдання. Завдання 1 → метод А. Завдання 2 → метод Б.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Об'єкт і предмет: не плутай</b><br>Об'єкт — явище/процес, що існує незалежно від дослідника (широке поле). Предмет — конкретний аспект об'єкта, що вивчається (вузький фокус). Не може бути навпаки.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перевірка узгодженості</b><br>Мета → Завдання → Висновки мають утворювати ланцюг. Висновок 1 відповідає завданню 1. Метод відповідає завданню. Якщо ланцюг розірваний — структура дослідження хибна.</div></div><div class=\"final-note\">📌 Типова помилка: мета і завдання формулюються як «дослідити», «вивчити», «розглянути». Мета має бути конкретнішою: «визначити взаємозв'язок між X і Y», «розробити модель Z».</div>"],[221,"Академічна реструктуризація","<div class=\"rule-note\">🔧 <b>Реструктуризація тексту</b> — коли зміст є, але структура не працює. Редагування структури ефективніше ніж переписування — правиш архітектуру, а не цеглини.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Reverse outline (зворотний план)</b><br>Після написання: прочитай кожен абзац і запиши одним реченням його суть. Отримав новий план. Порівняй з початковим. Де розбіжності — там структурна проблема.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Переміщення абзаців</b><br>Якщо ідея А логічно передує ідеї Б, але стоїть після — переміщуй. Правило: читач не має повертатись назад, щоб зрозуміти поточне речення.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перевірка переходів</b><br>Перше речення кожного абзацу має логічно витікати з останнього речення попереднього. «Крім того,», «Однак,», «У контексті цього,» — маркери зв'язку. Відсутність зв'язку = структурна пробоїна.</div></div><div class=\"final-note\">💡 Правило пірамідального письма (Minto): головна ідея — на початку, деталі — після. Академічний текст часто порушує це: головний висновок ховається в кінці. Переставляй.</div>"]]},{"n":"🎓 БЛОК 2: Курсові, бакалаврські та магістерські роботи","e":"","cards":[[222,"Структура кваліфікаційної роботи","<div class=\"rule-note\">📝 <b>Кваліфікаційна робота</b> (бакалаврська, магістерська) — документ з жорсткими структурними вимогами. Порушення структури = зниження оцінки незалежно від змісту.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Обов'язкові структурні елементи</b><br>Титульна сторінка. Анотація (укр + англ). Зміст. Перелік умовних скорочень. Вступ. Розділи (2–4). Висновки. Список використаних джерел. Додатки.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Вступ: 8 обов'язкових елементів</b><br>Актуальність → Мета → Завдання → Об'єкт → Предмет → Методи → Наукова новизна → Практичне значення. Кожен — окремий абзац або підрозділ.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Розділи: внутрішня логіка</b><br>Розділ 1 — теоретичний (що відомо). Розділ 2 — методологічний або аналітичний (як досліджуємо). Розділ 3 — практичний або результати. Між розділами — підсумки розділу.</div></div><div class=\"final-note\">📌 Вимоги варіюються по університетах і спеціальностях. ЗАВЖДИ перевіряй методичні рекомендації своєї кафедри — вони мають пріоритет над будь-якими загальними порадами.</div>"],[223,"Формулювання понятійного апарату","<div class=\"rule-note\">📖 <b>Понятійний апарат</b> — точне визначення термінів, якими ти користуєшся. Дослідник без визначень — це архітектор без специфікацій матеріалів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Навіщо визначати терміни</b><br>Один термін може означати різне в різних дисциплінах. Автор зобов'язаний сказати: «У цій роботі під X розуміємо…». Інакше читач сам підставить своє значення.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Три рівні визначень</b><br>1. Запозичене: «За Петренком (2020), X — це…». 2. Уточнене: «Прийнявши за основу визначення Петренка, уточнимо, що…». 3. Авторське: «У контексті даного дослідження під X розуміємо…»</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Оформлення в тексті</b><br>Перше вживання терміна — з визначенням або посиланням на нього. Перелік визначень у «Вступі» або окремому підрозділі «Понятійний апарат». Узгодженість: один термін — одне значення по всій роботі.</div></div><div class=\"final-note\">💡 Пастка: починати роботу, не визначивши ключові терміни. Через 20 сторінок виявляється, що під «мотивацією» малося на увазі два різних явища одночасно.</div>"],[224,"Обґрунтування вибору методів","<div class=\"rule-note\">⚗️ <b>Обґрунтування методів</b> — не «ми використали анкетування», а «ми використали анкетування, тому що це оптимально для нашого питання і вибірки». Наука — це аргументований вибір.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Три питання для обґрунтування</b><br>1. Чому цей метод відповідає дослідницькому питанню? 2. Чому не альтернативні методи? 3. Які обмеження обраного методу і як ми їх враховуємо?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Відповідність метод → тип даних</b><br>Якісні дані (думки, досвід, значення) → інтерв'ю, фокус-групи, аналіз документів. Кількісні (числа, частоти, зв'язки) → опитування, експеримент, контент-аналіз.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Тріангуляція</b><br>Поєднання кількох методів підвищує валідність. Опитування + інтерв'ю = кількісна картина + якісне пояснення. Це сильніша позиція, ніж один метод.</div></div><div class=\"final-note\">📌 Шаблон: «Для досягнення мети дослідження було обрано [метод], оскільки він дозволяє [що саме]. Це відповідає рекомендаціям [посилання]. Обмеженням є [X], що враховано через [Y]».</div>"],[225,"Написання теоретичного розділу","<div class=\"rule-note\">📚 <b>Теоретичний розділ</b> — не переказ підручників. Це синтез літератури, що показує: ти знаєш контекст і позиціонуєш своє дослідження в ньому.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура теоретичного розділу</b><br>1. Огляд ключових концепцій (що відомо загалом). 2. Аналіз підходів і теорій (як пояснюють). 3. Порівняння і суперечності. 4. Позиціонування свого дослідження («У нашій роботі прийнятий підхід X, тому що…»).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Не переказуй — синтезуй</b><br>НЕ «Петренко (2020) стверджує A. Коваль (2021) стверджує B.» → «Більшість дослідників (Петренко, 2020; Коваль, 2021) погоджуються щодо A, однак питання B залишається дискусійним».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Критична позиція</b><br>Автор погоджується, частково погоджується або не погоджується з джерелами — і пояснює чому. Відсутність критичної позиції = реферат, а не наукова робота.</div></div><div class=\"final-note\">💡 Тест: прочитай теоретичний розділ, закривши список джерел. Якщо він читається як твій текст, а не колаж цитат — добре написаний. Якщо без джерел не зрозуміло нічого — ти переказував, а не синтезував.</div>"],[226,"Розробка практичного розділу","<div class=\"rule-note\">🔬 <b>Практичний розділ</b> — серце кваліфікаційної роботи. Тут показується власний внесок: що ти зробив, як, що отримав.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура практичного розділу</b><br>1. Організація дослідження (де, коли, з ким, як). 2. Методика збору даних (детально). 3. Результати (факти, числа, таблиці). 4. Аналіз і інтерпретація (що це означає).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Результати vs. інтерпретація</b><br>Результати: «72% респондентів зазначили X». Інтерпретація: «Це свідчить про Y, що узгоджується з теорією Z (посилання) і підтверджує гіпотезу».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Таблиці, рисунки, графіки</b><br>Кожен елемент — пронумерований і підписаний. У тексті — посилання: «(рис. 2.3)». Не залишай таблиці без коментаря — прокоментуй ключові числа.</div></div><div class=\"final-note\">📌 Типова помилка: практичний розділ = лише таблиці. Таблиці — ілюстрація, а не замінник аналізу. Завдання автора — пояснити читачу, що означають числа.</div>"],[227,"Формулювання наукової новизни","<div class=\"rule-note\">🌟 <b>Наукова новизна</b> — те, чого до тебе не існувало в науці. Не «я зробив огляд» і не «я застосував відомий метод». Конкретний внесок, який змінює наукове знання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Типи наукової новизни</b><br>Вперше встановлено: явище/закономірність, яких не знали. Уточнено: відоме поняття доповнено новими характеристиками. Удосконалено: відомий метод/підхід покращено. Розвинено: теорія розширена на нову галузь або вибірку.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як формулювати</b><br>Чіткий дієслів: «вперше встановлено», «удосконалено», «доведено». Конкретний об'єкт: що саме? Новизна порівняно з чим: «на відміну від підходу X». Результат: що це дає науці.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Типові помилки</b><br>«Питання розглянуто комплексно» — не новизна. «Вивчено особливості» — не новизна. «Запропоновано рекомендації» — це практичне значення, не новизна. Новизна — зміна знання, а не обсяг роботи.</div></div><div class=\"final-note\">📌 Шаблон: «Вперше [що зроблено] для [об'єкта/контексту], що дозволяє [результат для науки/практики], на відміну від [попередніх підходів], де [обмеження попередніх]».</div>"],[228,"Інтерпретація статистичних даних","<div class=\"rule-note\">Статистика описує, але не доводить — розуміти результати важливіше, ніж їх рахувати.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>p-значення</b><br>Показує ймовірність отримати такий результат <b>випадково</b>. p &lt; 0.05 — стандартний поріг значущості. Але малий p ≠ великий ефект і ≠ практична цінність.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Розмір ефекту</b><br>Cohen's d, η², r — показують <b>наскільки суттєвий</b> ефект. Малий ефект може бути значущим при великій вибірці — це не означає важливості результату.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Довірчий інтервал</b><br>95% ДІ показує діапазон, в якому знаходиться справжнє значення параметра з ймовірністю 95%. Вужчий ДІ = точніша оцінка.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Помилки I і II роду</b><br>Хибнопозитивний (α, зазвичай 0.05) — знайшли ефект якого немає. Хибнонегативний (β) — пропустили реальний ефект. Потужність тесту = 1−β, ціль ≥ 0.80.</div></div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Практичне правило</b><br>Завжди звітуй: n, M, SD, точне p, розмір ефекту, ДІ. Одне p-значення — неповний звіт.</div></div><div class=\"final-note\">APA 7 вимагає вказувати p &lt; .001 (не p = .000), розмір ефекту і ДІ у кожній таблиці результатів.</div>"],[229,"Формулювання висновків розділів","<div class=\"rule-note\">✍️ <b>Висновки розділу</b> — підсумок, а не переказ. Відповідають на питання: які завдання виконано в цьому розділі і що з цього випливає для наступного.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура висновків розділу</b><br>1. Що досліджувалось у розділі (1 речення). 2. Основні результати по кожному завданню розділу (нумерований перелік або абзаци). 3. Загальний висновок і перехід до наступного розділу.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Відповідність завданням</b><br>Перевір: кожне завдання вступу = один висновок десь у роботі. Висновки розділу 1 = теоретичне обґрунтування для розділу 2. Висновки розділу 2 = база для практичного розділу. Це ланцюг, а не окремі блоки.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мовні кліше</b><br>«Таким чином, у першому розділі…». «Аналіз показав, що…». «Встановлено, що…». «Результати підтверджують/спростовують гіпотезу про…». Уникай: «Отже, підсумовуючи вищевикладене…» — водяниста фраза.</div></div><div class=\"final-note\">📌 Тест: прочитай лише висновки всіх розділів підряд. Вони мають читатись як зв'язний текст і відповідати на дослідницьке питання. Якщо ні — є структурна проблема.</div>"],[230,"Розрахунок репрезентативної вибірки","<div class=\"rule-note\">Вибірка — це не просто \"скільки людей опитати\", а математично обґрунтована кількість для надійних висновків.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Формула Кохрана</b><br>n₀ = (Z²·p·q) / e² де Z=1.96 (95%), p=0.5 (макс. дисперсія), e=0.05 (похибка). Дає n₀≈384 для необмеженої генеральної сукупності.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Поправка для малих сукупностей</b><br>Якщо N &lt; 10 000: n = n₀ / (1 + n₀/N). Для N=1000: n = 384/(1+384/1000) ≈ 278. Менша сукупність → менша вибірка.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Калькулятори вибірки</b><br>Raosoft.com, SurveyMonkey calculator, G*Power (для статистичних тестів). Вводиш: рівень довіри, похибку, розмір популяції — отримуєш n.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Стратифікована вибірка</b><br>Якщо в генсукупності є важливі підгрупи (вік, стать, регіон) — формуй вибірку пропорційно. Простий приклад: 60% жінок у популяції → 60% у вибірці.</div></div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Типові орієнтири</b><br>Якісне дослідження: 15–30 інтерв'ю (до насичення). Кількісне: n≥30 мінімум, n≥100 для регресії, n≥200 для SEM/факторного аналізу.</div></div><div class=\"final-note\">Завжди обґрунтовуй вибірку у методологічному розділі: формула + вхідні параметри + отримане значення.</div>"],[231,"Опис обмежень дослідження (Limitations)","<div class=\"rule-note\">⚠️ <b>Обмеження дослідження</b> — не слабкість, а чесність. Дослідник, який пише про limitations, демонструє наукову зрілість. Відсутність обмежень у роботі = відсутність критичного мислення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Типи обмежень</b><br>Вибіркові: не репрезентативна або мала вибірка. Часові: один момент часу (cross-sectional). Методологічні: самозвіт може бути неточним. Географічні: результати для одного регіону. Операціоналізація: вимірювали proxy, а не сам конструкт.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як описувати</b><br>«Дане дослідження має ряд обмежень. По-перше, вибірка включала лише студентів одного університету, що обмежує узагальненість результатів. По-друге, поперечний дизайн не дозволяє встановити причинно-наслідкові зв'язки».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Зв'язок з майбутніми дослідженнями</b><br>Кожне обмеження = рекомендація для майбутніх: «Перспективним є проведення поздовжнього дослідження для встановлення причинності». Так limitations перетворюються на вклад у науку.</div></div><div class=\"final-note\">📌 Правило: 3–5 конкретних обмежень краще ніж «дослідження має певні обмеження». Загальна фраза — ознака того, що автор сам не розуміє меж своєї роботи.</div>"],[232,"Валідизація соціологічних анкет","<div class=\"rule-note\">📋 <b>Валідизація анкети</b> — перевірка, що питання вимірюють те, що мають вимірювати. Анкета без валідизації — ти не знаєш, що саме виміряв.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Змістова валідність (Content validity)</b><br>Чи охоплює анкета всі аспекти конструкта? Метод: попросити 3–5 експертів оцінити відповідність кожного питання концепту (1–5). CVI (Content Validity Index) ≥ 0.78 — прийнятно.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Конструктна валідність</b><br>Чи корелюють питання зі схожими вимірами (конвергентна) і не корелюють з несхожими (дискримінантна)? Метод: факторний аналіз — питання одного конструкта мають завантажуватись на один фактор.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Пілотне тестування</b><br>Анкету на 20–30 осіб перед основним дослідженням. Питання: середній час заповнення? Які питання незрозумілі? Де більше пропусків? Альфа Кронбаха ≥ 0.70 для шкал. Корегуй до досягнення прийнятних показників.</div></div><div class=\"final-note\">💡 Найпоширеніша помилка: написати анкету → одразу опитувати. Завжди: анкета → перевірка → пілот → основне дослідження. Пілот рятує від катастрофи з даними.</div>"],[233,"Підготовка тез до конференції","<div class=\"rule-note\">📄 <b>Тези конференції</b> — 1–3 сторінки, що представляють дослідження. Перший академічний друкований доробок для більшості студентів. Відрізняється від статті стислістю і відсутністю повного методологічного опису.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура тез</b><br>Назва (конкретна, не загальна). Автор(и), установа. Актуальність (1–3 речення). Мета і завдання. Методи (коротко). Основні результати (конкретні числа/факти). Висновки (1–2 речення). Список літератури (3–5 позицій).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Типові помилки</b><br>Назва = тема роботи, а не результат. «Встановлено, що проблема існує» — не результат. Загальні слова без цифр. Список літератури зі шкільних підручників. Перевищення ліміту сторінок.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як обрати конференцію</b><br>Студентські секції при університетах (низький поріг входу). Всеукраїнські студентські конференції. Перевір: є у переліку ВАК/МОН? Збірник отримує ISBN/ISSN? Матеріали конференції — це твій перший офіційний науковий доробок.</div></div><div class=\"final-note\">📌 Лайфхак: тези — скорочена версія вступу + результати + висновки дипломної роботи. Якщо диплом готується паралельно, напиши тези спочатку — вони структурують думку.</div>"],[234,"Написання статті за стандартом IMRAD","<div class=\"rule-note\">📰 <b>IMRAD</b> — Introduction, Methods, Results, And Discussion. Стандартна структура наукової статті в природничих і соціальних науках. Більшість рецензованих журналів вимагає її.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Introduction (Вступ)</b><br>Funnel-структура: широкий контекст → вузька проблема → прогалина → мета. Завершується Research question або гіпотезою. Коротко: 400–600 слів. Посилань: 15–25.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Methods (Методи)</b><br>Відтворюваність — головний критерій. Хтось інший має змогу повторити дослідження за твоїм описом. Дизайн → вибірка → інструменти → процедура → аналіз. Не пояснюй навіщо метод — описуй що і як.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Results і Discussion</b><br>Results: факти без інтерпретації. «Група A показала M=72.3». Discussion: інтерпретація + зіставлення з літературою + обмеження + практичне значення. «Це свідчить про X, що узгоджується з Петренко (2020), однак суперечить...»</div></div><div class=\"final-note\">📌 Abstract = мініверсія IMRAD: по 1–2 реченню на кожну секцію + висновок. Пишеться останнім. Ключові слова: 5–7, не з назви статті — додаткові пошукові терміни.</div>"],[235,"Взаємодія з науковим керівником","<div class=\"rule-note\">🤝 <b>Науковий керівник</b> — не вчитель і не замовник. Це наставник: він вказує напрям, але роботу робиш ти. Правильна взаємодія вдвічі прискорює написання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Формат регулярних зустрічей</b><br>Перед кожною зустріччю: надіслати оновлений матеріал за 24–48 год. На зустрічі: конкретні питання, а не «що мені робити далі». Після зустрічі: конспект домовленостей на email керівнику. Це захищає тебе і структурує процес.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як ставити питання</b><br>НЕ «Як мені написати методологічний розділ?». ТАК: «Я планую використати анкетування (N=150, Likert 5), чи відповідає це меті дослідження?» Прийди з рішенням — проси підтвердження або корекцію.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли виникають суперечності</b><br>Якщо вимоги керівника суперечать методичним рекомендаціям кафедри — уточни у керівника: пріоритет методичок чи його вимог? Задокументуй домовленість. При конфлікті — звернись до методиста кафедри.</div></div><div class=\"final-note\">💡 Правило трьох: кожне питання, яке ти несеш керівнику, мусить супроводжуватись трьома варіантами відповіді, з яких ти вже обрав один. Керівник підтверджує або коригує — не придумує за тебе.</div>"],[236,"Робота з рецензіями","<div class=\"rule-note\">📝 <b>Відповідь на рецензію</b> (Response to Reviewers) — окремий жанр академічного письма. Навіть якщо рецензент помилився — твоя відповідь має бути коректною і конструктивною.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура відповіді</b><br>Подяка рецензенту (1 речення). По кожному зауваженню: 1) цитата коментаря, 2) твоя відповідь («Погоджуємося/Не погоджуємося, тому що…»), 3) зміни у рукописі («Додано рядок X на с. Y»).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Якщо не погоджуєшся</b><br>«Дякуємо за зауваження. Ми не можемо погодитися з цим твердженням, оскільки [аргумент + посилання]. Однак ми уточнили формулювання на с. 7 для усунення можливої двозначності». Завжди роби хоча б мінімальну зміну.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Навіщо вміти це студенту</b><br>Курсові/дипломні проходять захист — це теж форма рецензування. Відповіді на зауваження комісії — той самий формат. Вміння конструктивно відповідати на критику — наскрізна навичка.</div></div><div class=\"final-note\">📌 Золоте правило: рецензент витратив час на твою роботу — поважай це. Навіть різка критика часто вказує на реальну проблему. «Reviewer 2» — мем, але і вчитель.</div>"],[237,"Оформлення додатків у дипломі","<div class=\"rule-note\">📎 <b>Додатки</b> — матеріали, що підтверджують дослідження, але занадто великі або деталізовані для основного тексту. Ні без них не обійтись, ні перевантажувати ними основний текст не варто.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що виносити в додатки</b><br>Анкети і гайди інтерв'ю (повний текст). Великі таблиці з первинними даними. Розрахунки вибірки. Акти впровадження. Скриншоти програм. Код скриптів аналізу. Статистичні виводи SPSS/R.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Оформлення</b><br>Позначення: Додаток А, Б, В (або A, B, C залежно від вимог). Заголовок над додатком. У тексті роботи: обов'язкове посилання «(Додаток А)». Нумерація сторінок — продовження основного тексту або окрема.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Типові помилки</b><br>Додатки є, але в тексті на них немає посилань. Дублювання: те, що є в додатку, переказується в тексті повністю. Відсутній заголовок. Не вказаний зв'язок з дослідженням.</div></div><div class=\"final-note\">📌 Правило: якщо додаток не згаданий у тексті — він не потрібен. Якщо без додатка неможливо перевірити результати — він обов'язковий. Мінімальний обов'язковий: анкета і таблиця первинних даних.</div>"],[238,"Перевірка на академічну доброчесність","<div class=\"rule-note\">🔍 <b>Академічна доброчесність</b> — не лише «чи є плагіат». Це цілий кодекс: коректне цитування, власний аналіз, відсутність фабрикації даних, прозорість методів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Програми перевірки</b><br>Unicheck (поширений в Україні). Turnitin (міжнародний стандарт). Plagiat.pl. Strikeplagiarism. Показник оригінальності 70–80%+ = прийнятно, але вимоги різняться по університетах і кафедрах.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Що перевіряють і що є плагіатом</b><br>Пряме копіювання без лапок = плагіат. Перефразування без посилання = плагіат. Переклад без вказання джерела = плагіат. Своя попередня робота без посилання = самоплагіат. Правильно: цитата в лапках + посилання або переказ + посилання.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Використання ШІ</b><br>Деякі університети заборонили або обмежили використання ChatGPT/ШІ. Є системи виявлення ШІ-тексту (GPTZero, Originality.ai). Дізнайся позицію своєї кафедри ДО написання. Прозорість краще ніж приховування.</div></div><div class=\"final-note\">💡 Доброчесність — не про уникнення покарання. Вона про повагу до авторів, чиїми ідеями ти користуєшся, і про власну інтелектуальну чесність. Коли цитуєш — дякуєш попередникам.</div>"],[239,"Трансформація диплома в портфоліо","<div class=\"rule-note\">💼 <b>Диплом → портфоліо</b> — рідкісна навичка. Більшість студентів «ховають» дипломну в шухляду. Але це 50–80 сторінок доробку, що демонструє роботодавцю реальні компетенції.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що витягнути з диплому</b><br>Методологічний розділ → демонструє вміння планувати дослідження. Аналітичний розділ → вміння працювати з даними і інструментами. Практичні рекомендації → вміння вирішувати реальні задачі. Список літератури → вміння шукати інформацію.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Формати для портфоліо</b><br>PDF одна сторінка «Summary»: проблема → метод → результат → висновок. GitHub зі скриптами аналізу (якщо є). LinkedIn: секція «Projects» з коротким описом. Слайд-деки: 5–7 слайдів «презентація проєкту».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мова презентації роботи</b><br>«Провів дослідження ефективності X на вибірці N=200» звучить краще ніж «написав диплом». «Використовував SPSS для аналізу даних» краще ніж «обробив дані». Результати в числах: «виявлено зниження показника на 23%».</div></div><div class=\"final-note\">📌 Порада: паралельно з написанням диплому веди «щоденник навичок» — що конкретно ти вмієш робити після кожного розділу. Після захисту — це готовий список компетенцій для резюме.</div>"],[240,"Складання автореферату","<div class=\"rule-note\">📄 <b>Автореферат</b> — стисла версія кваліфікаційної роботи (5–10% обсягу). Обов'язковий для магістерських і дисертацій. Перший документ, який читають рецензенти і члени комісії.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура автореферату</b><br>Загальна характеристика роботи (актуальність, мета, завдання, об'єкт/предмет, методи, новизна, практичне значення). Основний зміст (коротко по розділах). Висновки. Список публікацій автора (якщо є).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Вимоги до стислості</b><br>Кожен розділ — 1–2 абзаци. Лише найважливіші результати з числами. Жодної «води». Анотації у вступі — ті самі формулювання, що у вступі роботи. Автореферат не переказує — він анотує.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Технічні вимоги</b><br>ДСТУ і вимоги кафедри: зазвичай А5, 10–12 сторінок. Перелік публікацій — за ДСТУ ГОСТ 7.1:2006. Якщо вимагається — окремий аркуш «Відгук наукового керівника».</div></div><div class=\"final-note\">💡 Порада: пиши автореферат після завершення роботи, але до захисту — 2–3 дні. Якщо важко стиснути — значить у роботі немає чіткої структури результатів. Автореферат — лакмус.</div>"],[241,"Підготовка до нормоконтролю","<div class=\"rule-note\">📐 <b>Нормоконтроль</b> — перевірка дотримання технічних вимог до оформлення. В Україні — обов'язковий крок перед захистом. ⚠️ Вимоги різняться між університетами і навіть кафедрами — завжди перевіряй методичку свого вишу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Типові вимоги (орієнтир — уточнюй)</b><br>Шрифт: Times New Roman 14, міжрядковий 1.5. Поля: ліве 2.5 см, праве 1.5 см, верх/низ 2 см — <b>але це найпоширеніший варіант, не стандарт</b>. Нумерація сторінок: з другої. Заголовки: без крапки в кінці. Відступ абзацу: 1.25 см.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Нумерація ілюстрацій і таблиць</b><br>Рисунок 1.1 — перший рисунок першого розділу. Таблиця 2.3 — третя таблиця другого розділу. Підпис рисунку — знизу по центру. Назва таблиці — зверху ліворуч. У тексті — обов'язкове посилання перед елементом (не після).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Список літератури</b><br>ДСТУ ГОСТ 7.1:2006, APA або Ванкуверський стиль — уточни у кафедри. Відповідність: кожне посилання у тексті = позиція у списку і навпаки. Порядок: за алфавітом (спочатку кирилиця, потім латиниця) або за появою у тексті — залежить від вимог.</div></div><div class=\"final-note\">📌 Чек-лист: поля ✓ шрифт ✓ відступи ✓ нумерація сторінок ✓ рисунки підписані ✓ таблиці пронумеровані ✓ список літератури відповідає посиланням ✓ Знайди методичку оформлення своєї кафедри — це єдиний авторитетний документ.</div>"]]},{"n":"💻 БЛОК 3: Аналітика даних, інструменти та хард-скіли","e":"","cards":[[242,"Аналіз даних у spreadsheets","<div class=\"rule-note\">📊 <b>Excel/Google Sheets</b> — підходять для малих і середніх наборів даних до ~100 000 рядків. Знання цих інструментів на аналітичному рівні відрізняє тебе від більшості студентів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Ключові функції для аналізу</b><br>SUMIF/COUNTIF/AVERAGEIF — агрегація за умовою. VLOOKUP/INDEX+MATCH — зв'язування таблиць. PIVOT TABLE — миттєвий зведений аналіз. IFERROR — захист від помилок. UNIQUE+FILTER+SORT — динамічні масиви (доступні у Google Sheets і Excel 365/2019+, не у старіших версіях Excel).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Зведені таблиці (Pivot Tables)</b><br>Вибери дані → Insert → Pivot Table. Рядки = категорії. Значення = числа з агрегацією (SUM/COUNT/AVG). Фільтри = умови. Це замінює десятки формул. Навчись за 2 год — окупиться сотнями годин аналізу.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Візуалізація в spreadsheets</b><br>Scatter plot → кореляції. Bar chart → порівняння категорій. Line chart → динаміка. Sparklines → мінімальна динаміка прямо в клітинці. Уникай 3D-діаграм — вони спотворюють дані і виглядають непрофесійно в академічних роботах.</div></div><div class=\"final-note\">📌 Правило: дані — окремий лист, аналіз — окремий лист, графіки — окремий лист. Первинні дані НІКОЛИ не редагуй — тільки копія. Формули — з посиланнями на клітинки, не з числами вручну.</div>"],[243,"Статистичні пакети (SPSS / R / Python)","<div class=\"rule-note\">🧮 <b>Статистичні пакети</b> — для серйозного аналізу. SPSS — зручний GUI, стандарт соціальних наук (але платний). R — потужний, безкоштовний, академічний стандарт. Python — найуніверсальніший.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>SPSS: коли і як отримати</b><br>Зручний без навичок програмування — аналізи через меню. Стандарт у соціології, психології, педагогіці. <b>⚠️ SPSS платний (~$100+/міс)</b> — доступний зазвичай лише через університетську ліцензію. Безкоштовна альтернатива: <b>JASP</b> — той самий логіки GUI, відкрита наука, безкоштовно.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>R: безкоштовний академічний стандарт</b><br>Безкоштовний і відкритий. ggplot2 — найкраща бібліотека для наукової візуалізації. tidyverse — зручна робота з даними. Відтворюваний скрипт — стандарт відкритої науки. RStudio — зручне середовище для початківців.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Python: для технічних спеціальностей</b><br>pandas + numpy — маніпуляції з даними. scipy + statsmodels — статистика. matplotlib/seaborn — візуалізація. scikit-learn — машинне навчання. Jupyter Notebook — інтерактивний аналіз з документацією прямо в браузері.</div></div><div class=\"final-note\">📌 Вибір: напиши назву свого напряму + «statistics software» в Google Scholar. Яке ПЗ переважає у статтях галузі — те і вчи. JASP і R — повноцінна заміна SPSS для студента без університетської ліцензії.</div>"],[244,"Автоматизація збору даних","<div class=\"rule-note\">🤖 <b>Автоматизація збору</b> — коли даних багато і збирати вручну неефективно. Навіть без програмування є інструменти для автоматизації опитувань, моніторингу, агрегації.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Онлайн-опитування і форми</b><br>Google Forms → автоматично в Google Sheets. SurveyMonkey → export у Excel/SPSS/CSV. Typeform → зручний UX, підвищує completion rate. QR-код → роздай у класі/аудиторії → дані одразу у хмарі.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Web scraping (для відкритих даних)</b><br>Python + BeautifulSoup/Scrapy — для технічних. Import.io, Octoparse — без коду. Завжди перевіряй robots.txt і Terms of Service. Академічний пошук: бази даних через API (Crossref, PubMed API).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Автоматизація повторюваних задач</b><br>Google Sheets macros — автоматизація очищення даних. Zapier/Make — зв'язування онлайн-сервісів без коду. Power Automate (Microsoft) — корпоративний стандарт. Автоматизація 2 год роботи займає 2 год налаштування — окупається при повторенні.</div></div><div class=\"final-note\">💡 Правило: кожного разу коли робиш одне й те саме вручну тричі — це кандидат на автоматизацію. Запитай себе: чи займе написання скрипту менше часу, ніж робити це 10 разів вручну?</div>"],[245,"Етичне використання ШІ у навчанні","<div class=\"rule-note\">🤖 <b>ШІ у навчанні</b> — потужний інструмент, що потребує відповідального використання. Питання не «чи можна», а «як використовувати щоб навчатись, а не обходити навчання».</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Де ШІ допомагає навчанню</b><br>Пояснення концепцій з різних кутів. Генерація прикладів і задач для практики. Зворотний зв'язок на чернетки. Допомога з редагуванням (не написанням). Пошук і структуризація інформації — з подальшою верифікацією джерел.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Де ШІ шкодить навчанню</b><br>Генерація відповідей замість самостійного мислення. Написання текстів без розуміння. Довіра без перевірки (ШІ галюцинує факти і посилання). Формування залежності без розвитку власних навичок.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Академічна чесність з ШІ</b><br>Дізнайся позицію своєї кафедри/університету. Розкривай використання ШІ якщо вимагається. Перевіряй кожен факт з ШІ-відповіді. Використання ШІ для генерації ідей → добре. Використання для генерації тексту без розуміння → проблема.</div></div><div class=\"final-note\">📌 Критерій: після роботи зі ШІ ти знаєш і розумієш більше? Якщо так — це навчання. Якщо ні — це ухилення від навчання. ШІ — помічник, не замінник власної думки.</div>"],[246,"Створення наукових ілюстрацій","<div class=\"rule-note\">Якісна ілюстрація говорить більше, ніж абзац тексту — але лише якщо вона точна, читабельна і відповідає вимогам видання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Вектор vs растр</b><br>SVG/PDF — масштабуються без втрат, ідеальні для схем і графіків. PNG/TIFF — для фотографій і мікроскопії. Більшість журналів вимагають 300+ DPI для растру, вектор — завжди кращий.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Графіки даних (Python)</b><br>Matplotlib — базовий, повний контроль. Seaborn — статистичні графіки з мінімальним кодом (побудовано поверх matplotlib). Plotly — інтерактивні графіки для веб/презентацій.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Схеми і діаграми</b><br>Draw.io / diagrams.net — безкоштовно, експорт в SVG/PNG. Lucidchart — командна робота. BioRender — наукові ілюстрації (біологія, медицина). Inkscape — редактор векторної графіки.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Правила оформлення</b><br>Підписи до рисунків — під ілюстрацією, з номером (Рис. 1). Усі осі підписані з одиницями вимірювання. Легенда — всередині або поруч. Колір доступний для дальтоніків (ColorBrewer, viridis).</div></div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Дозволи та авторство</b><br>Чуже зображення — вказати джерело і отримати дозвіл. CC-ліцензія — перевірити умови (NC = не для комерційного). Власна ілюстрація — підпис \"автор\" або ПІБ.</div></div><div class=\"final-note\">Перед відправкою до журналу: перевір Author Guidelines → Figure Requirements. Формат, DPI, розмір, колірна модель (RGB/CMYK) — у кожного видання свої вимоги.</div>"],[247,"Вертстка наукових текстів у LaTeX","<div class=\"rule-note\">📐 <b>LaTeX</b> — система підготовки наукових документів. Стандарт у математиці, фізиці, комп'ютерних науках. Відрізняється від Word: ти пишеш код, компілятор форматує.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Навіщо LaTeX студенту</b><br>Автоматична нумерація формул, рисунків, розділів. Бібліографія через BibTeX — одна команда форматує всі посилання. Формули: \frac{a}{b}, \sum_{i=1}^{n} — читабельні і красиві. Шаблони університетів і журналів — підключив і пиши.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Початок роботи</b><br>Overleaf.com — онлайн LaTeX-редактор, нічого встановлювати. Для початку: \documentclass{article} → \begin{document} → текст → \end{document}. Шаблон кваліфікаційної: пошук «Ukrainian thesis LaTeX template» на GitHub.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Основні команди</b><br>\section{} \subsection{} — розділи. \textbf{} \textit{} — жирний/курсив. \begin{figure} \includegraphics{} \caption{} — рисунки. \cite{} → \bibliography{} — посилання. \begin{equation} → формули з нумерацією.</div></div><div class=\"final-note\">📌 Крива навчання LaTeX крута: перші 2–3 дні — фрустрація. Після 2 тижнів — швидше, ніж Word для великих документів. Якщо у твоїй галузі є формули або складна верстка — час інвестиції окупиться.</div>"],[248,"Спеціалізоване інженерне ПЗ","<div class=\"rule-note\">⚙️ <b>Інженерне ПЗ</b> — стандартні інструменти для різних технічних спеціальностей. Знання одного профільного пакету = конкурентна перевага при пошуку роботи.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>CAD/CAM системи</b><br>AutoCAD — 2D/3D креслення, стандарт у будівництві і машинобудуванні. SolidWorks/CATIA — 3D моделювання деталей і збірок. Fusion 360 (Autodesk, безкоштовно для студентів) — хмарне CAD. КОМПАС-3D — популярний в Україні.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Моделювання і симуляція</b><br>ANSYS — МКЕ-аналіз, теплообмін, механіка. MATLAB/Simulink — математичне моделювання, управління. LabVIEW — вимірювальні системи. Multisim/LTSPICE — схемотехніка. Більшість мають студентські ліцензії.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Галузеве ПЗ</b><br>GIS: ArcGIS/QGIS (безкоштовно) — географічні інформаційні системи. BIM: Revit — будівельне інформаційне моделювання. ERP: SAP (є навчальні версії) — управління підприємством. Дізнайся стандарт своєї галузі і встановлюй студентську версію зараз.</div></div><div class=\"final-note\">📌 Студентські ліцензії: Autodesk Education (autodesk.com/education) — безкоштовно для студентів. ANSYS Academic. MATLAB Campus (через університет). JetBrains студентська ліцензія (безкоштовно). GitHub Student Pack — десятки безкоштовних інструментів.</div>"],[249,"Робота з Open Data","<div class=\"rule-note\">🌐 <b>Open Data</b> — відкриті набори даних від урядів, міжнародних організацій, дослідницьких інституцій. Безкоштовно, легально, готові до аналізу. Дипломна з реальними даними — одразу сильніша.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Де знайти відкриті дані</b><br>data.gov.ua — відкриті дані України. Eurostat — статистика ЄС. World Bank Open Data — економіка, розвиток. WHO Global Health Observatory. UNDP Human Development Reports. Kaggle — датасети для ML і аналізу.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як оцінити якість датасету</b><br>Дата оновлення. Методологія збору (є документація?). Пропущені значення. Одиниці вимірювання. Ліцензія (CC0, CC-BY — можна використовувати в роботі з посиланням).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Цитування відкритих даних</b><br>Автор/організація. Назва датасету. Версія або дата. URL. Дата доступу. Приклад: «World Bank Group. World Development Indicators (2024). URL: data.worldbank.org. Accessed: 2024-11-01».</div></div><div class=\"final-note\">💡 Порада: замість опитування 100 студентів розглянь аналіз відкритого датасету з тисячами спостережень. Більша вибірка, вища зовнішня валідність, більш значимі результати. І без бюрократії збору даних.</div>"],[250,"Економіко-математичне моделювання","<div class=\"rule-note\">Економіко-математичне моделювання — це мова для опису реальності числами. Модель корисна, якщо вона спрощує без спотворення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Регресійний аналіз</b><br>OLS (МНК) — лінійна залежність Y від X₁...Xₙ. Перевірки: нормальність залишків (Shapiro-Wilk), гомоскедастичність (Breusch-Pagan), відсутність автокореляції (Durbin-Watson).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Мультиколінеарність</b><br>Якщо незалежні змінні сильно корелюють між собою — коефіцієнти нестабільні. Діагностика: VIF &lt; 10 (ідеал &lt; 5). Рішення: виключити змінну або застосувати PCA.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Прогнозування часових рядів</b><br>ARIMA — для стаціонарних рядів після диференціювання. ETS (Holt-Winters) — для рядів з трендом і сезонністю. Пакети: Python statsmodels, R forecast.</div></div><div class=\"step c4\"><div class=\"step-num\">4</div><div class=\"step-text\"><b>Оптимізаційні моделі</b><br>Лінійне програмування (LP) — максимізація/мінімізація цільової функції за обмежень. Інструменти: Excel Solver, Python scipy.optimize, PuLP. Класика: задача про розклад, транспортна задача.</div></div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Верифікація моделі</b><br>Поділ вибірки: 70/30 або 80/20 (навчання/тест). Метрики: RMSE, MAE для регресії; AIC/BIC для порівняння моделей. Нижчий AIC = кращий баланс точності та складності.</div></div><div class=\"final-note\">Модель — не реальність, а її спрощення. Завжди вказуй обмеження: які припущення зроблено, де модель може не працювати.</div>"],[251,"Проведення глибинних інтерв'ю","<div class=\"rule-note\">🎙️ <b>Глибинне інтерв'ю</b> — якісний метод збору даних через розгорнуту бесіду. Дає розуміння досвіду, мотивів, значень — те, що анкета не вловлює.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Розробка гайду інтерв'ю</b><br>Гайд — не анкета. Це орієнтир, а не скрипт. Відкриті питання: «Розкажіть про...», «Як ви...», «Що для вас означає...». 5–8 тем по 2–3 питання. Уникай «так/ні». Почни з нейтральних, переходь до чутливих.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Технічні аспекти</b><br>Запис (з дозволу). Транскрипція (вручну або через Whisper/Otter.ai). Тривалість: 45–90 хв. Місце: нейтральне, зручне. Нотатки після — відразу: контекст, невербаліка, враження.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Аналіз якісних даних</b><br>Тематичний аналіз (Thematic Analysis, Braun & Clarke): 1) ознайомлення з даними, 2) початкове кодування, 3) пошук тем, 4) перевірка тем, 5) визначення і назва тем, 6) написання звіту. Програми: NVivo, Atlas.ti, MAXQDA.</div></div><div class=\"final-note\">💡 Принцип активного слухання: 70% часу — інформант говорить, 30% — ти направляєш. Мовчання — не страшне, дай людині думати. «Розкажіть більше» і «Що ви мали на увазі?» — найцінніші репліки інтерв'юера.</div>"],[252,"Аналітичні фреймворки (SWOT / PESTEL)","<div class=\"rule-note\">🔍 <b>Аналітичні фреймворки</b> — структуровані шаблони для аналізу ситуації. SWOT і PESTEL не дають відповідей самі по собі: цінність — у якості даних, що туди вносяться.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>SWOT-аналіз</b><br><b>S</b>trengths / <b>W</b>eaknesses — внутрішні фактори (що контролюємо). <b>O</b>pportunities / <b>T</b>hreats — зовнішні (що не контролюємо). Правило: кожен квадрант — конкретні факти, не загальні слова. «Хороша команда» — слабо. «3 розробники з досвідом у fintech» — сильно.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>PESTEL-аналіз</b><br>Зовнішнє середовище: <b>P</b>olitical, <b>E</b>conomic, <b>S</b>ocial, <b>T</b>echnological, <b>E</b>nvironmental, <b>L</b>egal. Використовується для стратегічного планування і в розділі «Аналіз зовнішнього середовища» наукових робіт. Кожен фактор — 1–3 конкретні пункти з джерелами.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як поєднувати</b><br>PESTEL → заповнює O і T у SWOT. SWOT → основа для стратегічних рішень. Матриця SO/ST/WO/WT: які стратегії випливають з кожної комбінації? SO — використовуй сильні сторони для можливостей. WT — мінімізуй слабкості, уникай загроз.</div></div><div class=\"final-note\">📌 Помилка: заповнити шаблон загальними фразами і вважати аналіз готовим. Критерій якості: кожен пункт можна підтвердити фактом або джерелом. SWOT без SO/ST/WO/WT — незавершений.</div>"],[253,"Організація фокус-груп","<div class=\"rule-note\">👥 <b>Фокус-група</b> — якісний метод збору даних: 6–10 учасників обговорюють тему під керівництвом модератора. Дає розуміння мотивів і думок, а не кількісних показників.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Підбір учасників</b><br>Однорідна група за ключовою ознакою (вік, досвід, роль) — різнорідна за іншими. Оптимальний розмір: 6–8 осіб. Менше 5 — мало думок, більше 10 — важко модерувати. Уникай людей, які знають одне одного тісно: соціальний тиск спотворює відповіді.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Структура сесії</b><br>Вступ (5 хв): правила, мета, дозвіл на запис. Розминкові питання (10 хв): легкі, щоб розговорити. Ключові питання (30–40 хв): відкриті, без навідних. Завершальне питання (5 хв): «Чи є щось важливе, що ми не обговорили?» Загальна тривалість: 60–90 хв.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Роль модератора</b><br>Не висловлює власну думку. Не підтверджує і не спростовує відповіді. Використовує техніки: «Розкажіть більше», «Що інші думають про це?», «Чому це важливо для вас?» Одночасно: спостерігач фіксує невербальні реакції.</div></div><div class=\"final-note\">📌 Аналіз: транскрибуй запис → виділи повторювані теми → кодування (thematic analysis). Фокус-група не репрезентативна статистично — не роби кількісних висновків («75% сказали»). Це якісні інсайти, не частоти.</div>"],[254,"Дашборди у Power BI / Tableau","<div class=\"rule-note\">📊 <b>Дашборд</b> — інтерактивна панель для моніторингу даних у реальному часі. Power BI (Microsoft, безкоштовний Desktop) і Tableau (платний, є Public безкоштовна версія) — два провідні інструменти.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Принципи хорошого дашборду</b><br>Одна мета — один дашборд. Не більше 5–7 ключових метрик на екрані. Ієрархія: найважливіше — зверху ліворуч (природній напрямок читання). Уникай pie charts для порівняння більше 3 категорій — bar chart читається точніше.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Power BI: основний робочий процес</b><br>Get Data → Transform (Power Query) → Model (зв'язки між таблицями) → Visualize → Publish. DAX-формули для обчислень: CALCULATE, SUMX, FILTER — базовий набір. Power BI Desktop — безкоштовний; публікація на web — потребує Pro ліцензії.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Tableau Public: безкоштовний варіант</b><br>Tableau Public — безкоштовний, але дашборди публічні (не для конфіденційних даних). Drag-and-drop інтерфейс — швидший старт ніж Power BI. Підключення: Excel, CSV, Google Sheets. Результат публікується на public.tableau.com.</div></div><div class=\"final-note\">📌 Вибір: Power BI — якщо організація використовує Microsoft 365. Tableau — якщо потрібна потужна візуалізація і є бюджет. Для студентських робіт: обидва мають безкоштовні версії. Альтернатива з кодом: Python (plotly dash) або R (shiny).</div>"],[255,"Побудова Second Brain","<div class=\"rule-note\">🧠 <b>Second Brain</b> — зовнішня система зберігання і організації знань. Концепція Тіаго Форте: розвантажити оперативну пам'ять мозку, зберігаючи ідеї, нотатки і матеріали у надійній системі.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Метод CODE</b><br><b>C</b>apture: зберігай все цінне одразу (думки, цитати, посилання). <b>O</b>rganize: за проєктами, а не за темами (де використовуватимеш?). <b>D</b>istill: виділяй суть — Bold + Progressive Summarization. <b>E</b>xpress: створюй щось нове з накопиченого.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Система папок PARA</b><br><b>P</b>rojects: активні проєкти з дедлайном. <b>A</b>reas: зони відповідальності без дедлайну (здоров'я, фінанси, навчання). <b>R</b>esources: теми, що можуть стати в пригоді. <b>A</b>rchives: неактивне з перших трьох категорій. Нотатка входить до Projects першою.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Інструменти</b><br>Obsidian — локальний, Markdown, безкоштовний, підтримує зв'язки між нотатками (граф знань). Notion — хмарний, гнучкий, безкоштовний для особистого використання. Logseq — відкритий код, орієнтований на щоденні нотатки. Вибір не критичний — важлива система, а не інструмент.</div></div><div class=\"final-note\">📌 Головна помилка: накопичувати без використання — «цифровий захаращення». Правило: нотатка має цінність лише якщо ти її повторно використав. Переглядай Weekly Review: що накопичилось → що можна використати → що застаріло → архів.</div>"],[256,"Написання технічного завдання (ТЗ)","<div class=\"rule-note\">📋 <b>Технічне завдання</b> — документ, що визначає що потрібно зробити, а не як. Погано написане ТЗ — головна причина провалу проєктів: виконавець зробив «правильно» за документом, але не те, що потрібно замовнику.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Обов'язкові розділи ТЗ</b><br>1) Мета і контекст: навіщо це потрібно. 2) Функціональні вимоги: що система робить. 3) Нефункціональні вимоги: швидкість, безпека, доступність. 4) Обмеження: бюджет, технології, терміни. 5) Критерії прийняття: як перевіримо що готово.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Мова ТЗ: точність понад усе</b><br>Уникай: «зручний», «швидкий», «простий» — не вимірювано. Пиши: «відповідь сервера — не більше 2 секунд при 100 одночасних запитах». Кожна вимога: хто робить, що робить, за яких умов, який результат. Формат: «Система повинна [дія] коли [умова] щоб [ціль]».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Use Cases і Wireframes</b><br>Use Case: сценарій взаємодії користувача з системою. «Користувач вводить email → система перевіряє формат → якщо коректний — надсилає лист підтвердження». Wireframe: схематичний макет інтерфейсу (Figma, Balsamiq, навіть папір) — знімає 80% питань про UI.</div></div><div class=\"final-note\">📌 Правило: підписане ТЗ — основа для прийняття і оплати роботи. Зміни після підписання — додаток до ТЗ з окремим погодженням. Стандарт в Україні: ДСТУ 3918-99 (для держзамовлень), але для більшості проєктів — достатньо структурованого документу у вільній формі.</div>"],[257,"A/B тестування та перевірка гіпотез","<div class=\"rule-note\">🧪 <b>A/B тест</b> — контрольований експеримент: дві групи отримують різні варіанти (A — контроль, B — зміна), порівнюємо метрику. Єдиний спосіб доказово перевірити, що зміна покращила результат.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правильна гіпотеза і метрика</b><br>Гіпотеза до тесту: «Зміна кнопки з сірої на зелену підвищить CTR на сторінці оформлення замовлення». Одна зміна — один тест. Первинна метрика — одна (не п'ять одночасно). Вторинні метрики — для контролю що не зламали інше.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Розмір вибірки і тривалість</b><br>Розмір вибірки розраховується до тесту (калькулятори: Evan's A/B test calculator, statsig.com). Залежить від: поточної конверсії, мінімального ефекту що хочемо виявити, рівня значущості (зазвичай p &lt; 0.05). Тест зупиняється після досягнення розрахованого розміру, а не «коли здається значущим».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Типові помилки A/B тестів</b><br>Peaking: зупинити тест щойно p &lt; 0.05 — хибно позитивний результат. Множинне тестування: 20 метрик одночасно → одна буде значущою випадково. Сезонність: тест у вихідні ≠ тест у будні. Розмір вибірки без розрахунку — результат ненадійний.</div></div><div class=\"final-note\">📌 Інструменти: Google Optimize (безкоштовний, до 2023 закрито → альтернативи: VWO, Optimizely), або самостійно через chi-square тест у Python/R. Статистична значущість ≠ практична значущість: p &lt; 0.05 при підвищенні конверсії на 0.01% — не варто впроваджувати.</div>"],[258,"Технічна документація","<div class=\"rule-note\">📝 <b>Технічна документація</b> — опис як система працює, щоб інший розробник (або ти через 6 місяців) міг з нею працювати без автора. Недокументований код — технічний борг.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Рівні документації</b><br>Код: коментарі для нетривіальних рішень (не «що робить», а «чому так»). Функції/API: docstrings з параметрами, типами і прикладами. Архітектура: README з описом структури, залежностей, як запустити. Процеси: runbooks для операційних процедур.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>README як мінімум</b><br>Обов'язково: що це, як встановити, як запустити, як запустити тести. Бажано: приклади використання, структура проєкту, як контрибутити. Markdown — стандарт для GitHub/GitLab. Badges (CI status, coverage) — швидкий сигнал про стан проєкту.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>API Documentation</b><br>OpenAPI/Swagger — стандарт для REST API: описує endpoints, параметри, відповіді, приклади. Генерується автоматично з анотацій (FastAPI, Spring Boot). Postman Collections — альтернатива для документування і тестування. Живий приклад запиту + відповіді — найцінніша частина API-доки.</div></div><div class=\"final-note\">📌 Правило: документація пишеться разом з кодом, не після. «Задокументуємо потім» = не задокументуємо ніколи. Docs-as-code: зберігай документацію в тому самому репозиторії, що і код — версіонується разом.</div>"],[259,"Аналіз нормативно-правової бази","<div class=\"rule-note\">⚖️ <b>Нормативно-правовий аналіз</b> — систематичне вивчення законів, підзаконних актів і стандартів, що регулюють досліджувану сферу. Обов'язковий розділ для юридичних, економічних, управлінських, медичних і педагогічних робіт.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Ієрархія нормативних актів в Україні</b><br>Конституція → Міжнародні договори → Закони України → Укази Президента → Постанови КМУ → Накази міністерств → Місцеві нормативні акти. Вищий акт має пріоритет. При суперечності норм — посилайся на вищий за ієрархією.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Пошук актуальних норм</b><br>Офіційні джерела: zakon.rada.gov.ua (Верховна Рада), oficialniydodatok.com.ua. Перевіряй дату редакції: закон міг зазнати змін — актуальна версія, а не первинна. Вказуй у роботі: «Закон України від [дата], в редакції від [дата остання зміна]».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Структура аналізу нормативної бази</b><br>1) Перелік актів за ієрархією. 2) Ключові положення, що стосуються теми. 3) Прогалини або суперечності в регулюванні — це може бути твоя research gap. 4) Порівняння з міжнародними стандартами (якщо релевантно).</div></div><div class=\"final-note\">📌 Помилка: цитувати застарілу редакцію закону. Завжди перевіряй «Поточна редакція» на zakon.rada.gov.ua. Якщо норма змінилась після подій, що досліджуєш — вказуй обидві редакції з датами.</div>"],[260,"Розробка дослідницьких опитувальників","<div class=\"rule-note\">📋 <b>Опитувальник</b> — інструмент збору первинних даних. Якість питань визначає якість даних. Погано сформульоване питання дає непридатні відповіді незалежно від розміру вибірки.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Типи питань</b><br>Закриті (варіанти відповіді): легко аналізувати, менше інформації. Шкала Лікерта (1–5 або 1–7): для вимірювання установок і думок. Відкриті: багато інформації, важко аналізувати кількісно. Правило: закриті питання — для кількісного аналізу, відкриті — для глибшого розуміння.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Правила формулювання питань</b><br>Одне питання = одна ідея (не «Наскільки зручний і корисний продукт?»). Уникай навідних питань («Чи погоджуєтесь ви, що X є важливим?»). Уникай подвійного заперечення. Використовуй зрозумілу лексику цільової аудиторії. Pilot test: протестуй на 3–5 людях до масового розсилання.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Структура опитувальника</b><br>Вступ: мета, анонімність, час заповнення. Демографічні питання: зазвичай наприкінці (не на початку — знижує залучення). Від загальних до конкретних. Від нейтральних до чутливих. Завершення: подяка і що буде з результатами.</div></div><div class=\"final-note\">📌 Інструменти: Google Forms (безкоштовно), SurveyMonkey (обмежена безкоштовна версія), Typeform (гарний UX). Довжина: до 10 хвилин заповнення — після цього різко падає якість відповідей. Завжди вказуй очікуваний час у вступі.</div>"],[261,"Бюджетування наукових проєктів","<div class=\"rule-note\">💰 <b>Бюджет наукового проєкту</b> — розпис усіх витрат для реалізації дослідження. Потрібен для грантових заявок, звітів і планування. Гранти відхиляють через нереалістичний або непрозорий бюджет.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Категорії витрат</b><br>Прямі: зарплата дослідників (найбільша стаття), обладнання, реактиви/матеріали, відрядження, публікаційні збори (APC). Непрямі (overhead): адміністративні витрати університету — зазвичай фіксований % від прямих (15–60% залежно від організації і гранту).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Обґрунтування кожної статті</b><br>Грантодавець перевіряє: чи кожна витрата необхідна і чи відповідає заявленій меті. Формат: «Витрати на відрядження: 2 конференції × 2 особи × $500 (реєстрація + переліт + проживання) = $2000». Числа з розрахунком — не округлені суми.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Контроль виконання бюджету</b><br>Щоквартальний моніторинг: виконання план/факт по статтях. Залишок — не завжди можна перекинути між статтями (залежить від правил гранту). Незаплановані витрати: потребують окремого погодження з грантодавцем. Веди облік з першого дня проєкту.</div></div><div class=\"final-note\">📌 Для студентських грантів (МОН, НФДУ): бюджет розраховується за ставками, встановленими законодавством. Перевір актуальні ставки перед складанням. Публікаційні збори (APC) у відкритих журналах Q1–Q2 — зазвичай $1500–3000: закладай заздалегідь.</div>"]]},{"n":"🎤 БЛОК 4: Публічний захист, наукова дискусія та софт-скіли","e":"","cards":[[262,"Доповідь на захисті диплома","<div class=\"rule-note\">🎓 <b>Захист диплому</b> — не переказ роботи, а презентація ключових результатів. Комісія вже читала (або мала читати) роботу. Завдання: показати, що ти розумієш що зробив і навіщо.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура доповіді (7–10 хвилин)</b><br>Вступ (1 хв): тема, мета, актуальність — одним реченням кожне. Методи (1–2 хв): що і як робив. Результати (3–4 хв): головне що отримав — з цифрами і слайдами. Висновки (1–2 хв): що доведено, практичне значення. Перспективи (30 сек): що далі.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Мова доповіді</b><br>Говори «я», а не «в роботі розглядається». Пасивний стан дистанціює тебе від результатів. «Я дослідив», «Я виявив», «Мій аналіз показав» — ти автор, ти відповідаєш. Уникай читання зі слайдів — комісія це помічає і сприймає негативно.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Підготовка до питань</b><br>Перечитай власну роботу за 2 дні до захисту. Знай слабкі місця — комісія знайде їх раніше за тебе. Підготуй відповіді на: «Чому обрав саме цей метод?», «Як перевіряв достовірність?», «Які обмеження дослідження?», «Де можна застосувати?».</div></div><div class=\"final-note\">📌 Регламент — строго. Якщо дали 7 хвилин — репетируй щоб вкластись у 6:30. Переходи: «Перейдемо до результатів», «Підсумовуючи» — структурують сприйняття. Зорний контакт з членами комісії — не лише з науковим керівником.</div>"],[263,"Презентація для захисту","<div class=\"rule-note\">📊 <b>Презентація для захисту</b> — візуальна підтримка доповіді, а не шпаргалка. Слайди з суцільним текстом — ознака непідготовленості. Правило: один слайд — одна ідея.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура і кількість слайдів</b><br>На 7–10 хвилин: 8–12 слайдів. Титульний (1) + Актуальність/мета (1) + Методи (1–2) + Результати (3–5, кожен результат окремо) + Висновки (1) + Дякую/Питання (1). Не роби слайд «Зміст» — він забирає час без цінності.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Оформлення</b><br>Шрифт: мінімум 24pt для тексту, 32pt+ для заголовків. Не більше 5–6 рядків тексту на слайді. Графіки і таблиці: читабельні з 5 метрів. Кольори: 2–3 максимум, достатній контраст. Уникай анімації — відволікає і гальмує.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Слайди з результатами</b><br>Числа — великим шрифтом, виділені кольором. Графік замість таблиці, де можливо. Підпис осей і одиниці вимірювання — обов'язково. «Рис. 2.1 — Динаміка показника X за 2020–2024 рр.» Якщо таблиця — тільки ключові рядки, не всі дані.</div></div><div class=\"final-note\">📌 Перевір на проєкторі або великому екрані до захисту — кольори і шрифт можуть виглядати інакше. Друкована версія для комісії (якщо вимагається): 6 слайдів на аркуш, чорно-біла — перевір читабельність.</div>"],[264,"Ведення наукової дискусії","<div class=\"rule-note\">🗣️ <b>Наукова дискусія</b> — обмін аргументованими позиціями для пошуку істини, а не перемоги в суперечці. Вміння дискутувати — ознака зрілого дослідника.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура аргументу</b><br>Теза → Доказ → Пояснення зв'язку. «Метод X ефективніший [теза], оскільки дослідження Іванченко (2022) показало підвищення точності на 15% [доказ], що пояснюється меншим впливом шуму у вибірці [пояснення]». Без доказу — це думка, не аргумент.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Відповідь на контраргумент</b><br>Не відкидай одразу. Схема: 1) Визнай сильну сторону («Це справедливе зауваження»). 2) Вкажи обмеження контраргументу. 3) Поверни до своєї позиції з новим кутом. Якщо контраргумент вагомий і ти не готовий — чесно: «Це потребує додаткового дослідження».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мова наукової дискусії</b><br>Нейтральна, без емоцій. «Дані свідчать», «Можна припустити», «На мою думку», «Є підстави стверджувати». Уникай: «Ви не розумієте», «Це очевидно», «Всі знають». Критикуй ідею, а не особу: «Цей підхід має обмеження» замість «Ви помиляєтесь».</div></div><div class=\"final-note\">📌 Корисна навичка: Steel-Manning — сформулюй позицію опонента у найсильнішому варіанті перш ніж критикувати. Це покращує якість дискусії і демонструє академічну зрілість.</div>"],[265,"Відповіді на зауваження опонентів","<div class=\"rule-note\">💬 <b>Зауваження опонента</b> на захисті — не атака, а частина наукового процесу. Мета комісії: переконатися що ти розумієш свою роботу і її обмеження. Правильна реакція — спокій і конкретика.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура відповіді на зауваження</b><br>1) Подякуй («Дякую за важливе зауваження»). 2) Переформулюй суть зауваження своїми словами — показуєш що зрозумів. 3) Відповідай по суті: погодься, якщо зауваження справедливе; поясни свою позицію, якщо не погоджуєшся. 4) Не затягуй — 1–2 хвилини максимум.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Коли зауваження справедливе</b><br>Не захищайся і не виправдовуйся. «Ви абсолютно праві — це обмеження дослідження, яке я зазначив у розділі X. У майбутніх дослідженнях це можна усунути шляхом Y». Визнання обмежень — ознака зрілості, не слабкості.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Коли не погоджуєшся</b><br>Поважно і з аргументами: «Я розумію цю позицію, однак у своїй роботі я виходив з [підстава]. Відповідно до [джерело/метод], цей підхід обґрунтований тим, що...» Не поступайся під тиском без аргументів — це теж слабкість.</div></div><div class=\"final-note\">📌 Підготовка: перечитай «Обмеження дослідження» і «Дискусія» — звідти беруться 80% зауважень. Якщо не знаєш відповіді: «Це цікаве питання, яке виходить за межі цієї роботи — потребує окремого дослідження». Це краще ніж вигадувати.</div>"],[266,"Нейтралізація провокаційних питань","<div class=\"rule-note\">🛡️ <b>Провокаційне питання</b> на захисті або конференції — рідко особиста атака. Зазвичай: перевірка меж компетентності, виявлення слабких місць методології або особиста дискусійність теми. Мета: зберегти спокій і відповісти по суті.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Технічне провокаційне питання</b><br>«Чому ви не використали метод X, який значно кращий?» Відповідь: поясни свій вибір з обґрунтуванням — обмеження даних, мета дослідження, доступні ресурси. Якщо метод X справді кращий — визнай і поясни чому не застосував (час, дані, компетенція).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Концептуальна провокація</b><br>«Вся ваша методологія хибна, тому що...» Не панікуй. Уточни: «Дякую. Якщо я правильно розумію, ви стверджуєте, що [переформулювання]. Чи вірно?» Це дає час зібратись і показує що ти слухаєш, а не реагуєш емоційно.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Питання поза компетенцією</b><br>Якщо питання про суміжну тему або деталь поза твоїм дослідженням: «Це виходить за межі мого дослідження. Однак, наскільки я знаю, [коротко]. Для точнішої відповіді потребую додаткового аналізу». Чесна межа компетентності — це нормально.</div></div><div class=\"final-note\">📌 Правило: не відповідай швидко на складне питання. Пауза 3–5 секунд — норма. «Дозвольте уточнити ваше питання» — легальний спосіб виграти час. Аудиторія на захисті зазвичай на твоєму боці.</div>"],[267,"Виступ на міжнародних конференціях","<div class=\"rule-note\">🌐 <b>Міжнародна конференція</b> — можливість представити дослідження, отримати зворотний зв'язок і розширити наукові зв'язки. Більшість проходять англійською. Доповідь: 10–15 хвилин + 5 хвилин питань.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Підготовка доповіді англійською</b><br>Пиши і репетируй текст — не імпровізуй. 10 хвилин = приблизно 1200–1400 слів у повільному темпі. Вимовляй кожне речення вголос: academia English відрізняється від розмовного. Запис себе на відео і перегляд — найефективніша підготовка.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Poster vs Oral presentation</b><br>Oral: більший престиж, складніше отримати. Poster: легше прийняти початківцям, дає можливість індивідуальних розмов з дослідниками. Poster session: будь готовий до 2-хвилинного pitch свого дослідження для кожного нового відвідувача.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Нетворкінг під час конференції</b><br>Прийди на coffee break з конкретним запитанням до доповідачів: «Ваш підхід до X дуже схожий на мій. Як ви вирішили проблему Y?» Обмін контактами — LinkedIn або email. Follow-up email протягом 48 год: «Дякую за розмову. Я зацікавлений у можливій співпраці щодо...»</div></div><div class=\"final-note\">📌 Пошук конференцій: WikiCFP, конференції асоціацій своєї галузі (IEEE, ACM, APA тощо). Deadlines для abstract зазвичай за 3–6 місяців. Студентські доповіді часто мають окремий трек з нижчою планкою прийняття.</div>"],[268,"Створення Poster Presentation","<div class=\"rule-note\">🖼️ <b>Poster Presentation</b> — наукова афіша розміром зазвичай A0 (84×119 см) або A1. Переглядається за 30–60 секунд стоячи. Мета: зацікавити настільки, щоб людина захотіла поставити питання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура постера</b><br>Зверху: назва (великий шрифт), автори, установа. Ліворуч зверху вниз: Вступ → Методи → Результати → Висновки. Правило читання: зліва направо, зверху вниз — колонками. Результати займають найбільше місця. Контактна інформація і QR-код на матеріали — внизу.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Оформлення</b><br>Шрифт заголовка: 72–96pt. Шрифт тексту: мінімум 24pt (читається з 1 метра). Мінімум тексту — максимум графіки. Білий простір — твій друг, не ворог. 2–3 кольори (корпоративний стиль університету + акцентний). Уникай суцільних блоків тексту.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>QR-код і цифрова версія</b><br>Розмісти QR-код на повну версію статті або препринту (arXiv, ResearchGate). Це дає контекст тим, хто хоче більше. Зроби також PDF-версію постера для розсилання після конференції. Figma, PowerPoint, Canva — підходять для верстки.</div></div><div class=\"final-note\">📌 Друк: замов у поліграфії мінімум за 3 дні до конференції. Перевір роздільну здатність зображень: мінімум 150 DPI для друку (300 DPI — ідеально). Бери з собою кілька копій бізнес-карток або QR-листівок.</div>"],[269,"Метод Science Slam","<div class=\"rule-note\">🎤 <b>Science Slam</b> — формат наукового виступу для широкої аудиторії: 10 хвилин, без жаргону, з гумором і енергетикою. Завдання: пояснити своє дослідження бабусі або старшокласнику.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Правила формату</b><br>Суворо 10 хвилин (є таймер, мікрофон вимикається). Без PowerPoint у класичному форматі (або мінімальний слайд). Мова: максимально проста і образна. Оцінка аудиторії: оплески — не академічна комісія. Переможець — хто найбільше зацікавив публіку.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Структура Science Slam виступу</b><br>Гачок (30 сек): несподіваний факт, жарт або питання — з першої секунди. Проблема (2 хв): чому це важливо, яка проблема в реальному житті? Рішення (5 хв): що я зробив, як це працює — без формул, через аналогії. Wow-момент (1 хв): найважливіший результат. Заклик (30 сек): що далі.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Техніки популяризації</b><br>Аналогія: «Це як [знайома річ], тільки [ключова різниця]». Масштаб: «Якби всі бактерії у вашому тілі...». Особиста історія: «Я почав цю роботу, коли...». Уникай абревіатур без пояснення. Репетируй з годинником — 10 хвилин суворо.</div></div><div class=\"final-note\">📌 Science Slam в Україні: scienceslam.com.ua. Формат корисний навіть без участі в заходах: вміння пояснити дослідження просто — ознака глибокого розуміння. Якщо не можеш пояснити просто — ймовірно, сам не до кінця розумієш.</div>"],[270,"Ораторська майстерність","<div class=\"rule-note\">🎙️ <b>Ораторська майстерність</b> — набір навичок, а не природній талант. Три компоненти комунікації: вербальна (слова), паравербальна (голос, темп, паузи), невербальна (поза, жести, зоровий контакт).</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Голос і темп</b><br>Темп публічного виступу: 120–150 слів на хвилину (повільніше ніж розмовна мова). Пауза — потужний інструмент: дай аудиторії обробити важливу думку. Гучність: говори до задніх рядів. Монотонність — головний ворог уваги: варіюй тон, підкреслюючи ключові слова.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Невербальна комунікація</b><br>Зоровий контакт: переводь погляд між секторами аудиторії, 2–3 секунди на людину. Поза: стій рівно, ноги на ширині плечей. Жести: природні, підсилюють слова. Уникай: схрещені руки, кишені, переступання з ноги на ногу, торкання обличчя.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Управління хвилюванням</b><br>Хвилювання фізіологічно і когнітивно схоже на збудження — переосмисли як «я готовий, мій організм мобілізований». Дихання: 4 рахунки вдих, 4 затримка, 6 видих — знижує ЧСС перед виступом. Перші 30 секунд найважчі: знай перший абзац напам'ять.</div></div><div class=\"final-note\">📌 Практика: Toastmasters (міжнародна організація з ораторства), записуй свої виступи на відео — найефективніший зворотний зв'язок. Правило 10 000 годин тут не потрібне: 20–30 виступів дають помітний прогрес.</div>"],[271,"Утримання уваги професорської ради","<div class=\"rule-note\">👨‍🏫 <b>Професорська рада</b> — досвідчена аудиторія, яка переглянула сотні захистів. Її увагу утримують: новизна, чіткість і впевненість. Загальні слова і читання зі слайдів — швидко вимикають увагу.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що цінує рада</b><br>Чіткість мети і гіпотези — з перших хвилин. Обґрунтований вибір методів. Усвідомлення обмежень дослідження. Конкретні цифри результатів. Рада оцінює не лише роботу, а й тебе як дослідника — наскільки глибоко ти розумієш свій матеріал.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Перші 2 хвилини — вирішальні</b><br>Починай з проблеми, а не з «Тема моєї роботи...». «Щороку в Україні X. Причина досі не встановлена. Мета мого дослідження — [конкретно]». Це захоплює увагу і відразу демонструє актуальність.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Технічні деталі — коротко</b><br>Рада не хоче почути все що в дипломі. Хоче почути: головний результат, чому він надійний і що з ним робити. Методологію — одним реченням («Використав регресійний аналіз для n=187»). Деталі — на питання.</div></div><div class=\"final-note\">📌 Після виступу: не перебивай питання, слухай до кінця. Якщо питання незрозуміле — уточни. Якщо відповіді немає — чесно скажи. Комісія поважає чесність більше за вигадані відповіді.</div>"],[272,"Пітчинг досліджень інвесторам","<div class=\"rule-note\">💼 <b>Pitch дослідження інвестору</b> — інший формат ніж академічний. Інвестор думає: який ринок, який продукт, яка команда, коли повернуться гроші. Дослідник думає: новизна, методологія, публікації.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Переклад з академічної на бізнесову мову</b><br>«Ми виявили кореляцію між X і Y» → «Ми знайшли спосіб знизити витрати на X на Y%, що на ринку коштує $Z». Кожен результат дослідження — питання «Що це означає для бізнесу?». Якщо не можеш відповісти — інвестор не зрозуміє цінності.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Структура pitch (3–5 хвилин)</b><br>Проблема: скільки це коштує ринку зараз (TAM). Рішення: що ти розробив, чим відрізняється від існуючого. Доказ: результати дослідження як валідація. Команда: чому ви можете це реалізувати. Ask: скільки потрібно і на що.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Захист IP до пітчу</b><br>Перед розкриттям деталей — NDA або хоча б збереження пріоритету: пріоритетна заявка на патент (utility patent application), препринт на arXiv (встановлює дату), або провізорний патент (США). Не розкривай ключові деталі технології без захисту.</div></div><div class=\"final-note\">📌 Програми: UNIT.City, Startup Ukraine, МОН-грантові програми для комерціалізації досліджень. Технологічні трансфери: в університетах зазвичай є відділ комерціалізації — звернись туди першим.</div>"],[273,"Організація наукового семінару","<div class=\"rule-note\">📐 <b>Науковий семінар</b> — структурована зустріч для обміну ідеями, обговорення досліджень або навчання. На відміну від конференції — менший формат, більше інтерактивності.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Планування: за 3–4 тижні</b><br>Визнач мету: представлення роботи, peer review, навчальний семінар? Доповідачі: 1–3, заздалегідь з підтвердженням. Формат: доповідь (20–30 хв) + дискусія (15–20 хв) або workshop (практичні вправи). Комунікація: запрошення + нагадування за 2 дні.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Модерація семінару</b><br>Представ доповідача коротко (1–2 речення + регалії). Слідкуй за часом — м'яко зупиняй при перевищенні. Дискусія: почни з підготовленого питання якщо тиша. «Хто хотів би прокоментувати методологію?» — конкретно. Завершуй підсумком ключових думок.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Документування і follow-up</b><br>Запис відео (за згодою учасників). Нотатки з ключовими тезами і action items — розсилай протягом 24 год. Зберігай матеріали (слайди, препринти) у спільній папці. Цикл: один семінар → наступний через 3–4 тижні → формується традиція.</div></div><div class=\"final-note\">📌 Онлайн-семінари (Zoom/Meet): окремий модератор для чату і питань. Записуй і публікуй на YouTube — це розширює аудиторію і підвищує видимість дослідницької групи. Gather.town або Miro — для інтерактивних воркшопів.</div>"],[274,"Академічне листування","<div class=\"rule-note\">✉️ <b>Академічне листування</b> — email до рецензента, редактора журналу, наукового керівника або іноземного колеги. Формат і тон суттєво відрізняються від ділового листування.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Звернення до редактора / рецензента</b><br>Subject: чіткий («Re: Manuscript #XXXX — Response to Reviewers»). Звернення: «Dear Professor [Прізвище]» або «Dear Editor». Тон: формальний, ввічливий, конкретний. Структура відповіді рецензенту: кожне зауваження → твоя відповідь → зміни у рукописі (рядки).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Cold email до потенційного наукового керівника</b><br>Перший абзац: хто ти, звідки дізнався про них. Другий: конкретно яка їхня робота тебе зацікавила (не загальна похвала). Третій: що ти пропонуєш — тема, досвід, чого шукаєш. Четвертий: прохання і наступний крок. Прикріпи CV і 1–2 сторінки research proposal.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Листування між колегами</b><br>При першому контакті: повне ім'я + афіліація. При запиті статті: «Would you be willing to share a preprint of your recent paper on X?» — це стандартний і прийнятний запит. Дотримуйся обіцяних дедлайнів листування: затримка без попередження в академії — погана репутація.</div></div><div class=\"final-note\">📌 Стандарт відповіді в академії: 48–72 год для рядових листів; до тижня для складних. Якщо відповіді немає через тиждень — один follow-up нормальний. Більше — нав'язливо. Зберігай важливе листування: воно може стати документальним підтвердженням домовленостей.</div>"],[275,"Академічний нетворкінг","<div class=\"rule-note\">🤝 <b>Академічний нетворкінг</b> — побудова професійних стосунків у науковій спільноті. Більшість можливостей (гранти, співпраця, постдоки) передаються через особисті зв'язки, а не через відкриті оголошення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Онлайн-присутність дослідника</b><br>ORCID iD: безкоштовний унікальний ідентифікатор — зареєструйся на orcid.org. Google Scholar профіль: налаштуй автоматичне відстеження цитувань. ResearchGate: платформа для обміну препринтами і контактів. LinkedIn: для зв'язків поза академією і з індустрією.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Конференції як нетворкінг-інструмент</b><br>До конференції: переглянь програму, виділи 3–5 людей, з якими хочеш познайомитись. Під час: кава-брейки цінніші за пленарні сесії для знайомств. Після: follow-up email до 48 год. «Дякую за цікаву дискусію щодо X. Буду радий обмінятись препринтами».</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Менторство і зворотне менторство</b><br>Знайди ментора на 2–3 кроки попереду у кар'єрі. Пропонуй щось конкретне: допомогу з аналізом даних, переклад, технічні навички. Зворотне менторство: старший дослідник + молодший, що добре знає нові технології чи соцмережі — взаємовигідно.</div></div><div class=\"final-note\">📌 Написати першому — нормально. Академія цінує ініціативу. Персоналізоване повідомлення («Я читав вашу роботу про X і маю питання щодо...») відповідають частіше, ніж загальні. Twitter/X — несподівано активна академічна спільнота (#AcademicTwitter).</div>"],[276,"Переговори про авторство","<div class=\"rule-note\">📜 <b>Авторство у науковій статті</b> — не подяка, а визнання інтелектуального внеску. Суперечки про авторство — одна з найчастіших етичних проблем в академії. Правила визначені до початку роботи, а не після.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Критерії авторства ICMJE</b><br>Усі чотири умови: 1) суттєвий внесок у концепцію або дизайн АБО збір/аналіз/інтерпретація даних; 2) участь у написанні або критичному рецензуванні; 3) затвердження фінальної версії; 4) відповідальність за точність роботи. Хто не відповідає всім чотирьом — Acknowledgements, не автор.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Порядок авторів</b><br>Перший автор: найбільший внесок у написання і дослідження. Останній автор: зазвичай старший дослідник/науковий керівник (senior authorship). Середні автори: за внеском (домовленість у команді). CRediT taxonomy — стандарт опису ролей кожного автора.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як уникнути конфліктів</b><br>Визнач ролі і авторство ДО початку роботи — письмово. Якщо хтось приєднується пізніше — переглянь угоду. Корреспондентський автор (corresponding author): відповідає за комунікацію з редакцією — окремо від порядку авторів. Зміна авторства після подачі статті — потребує письмового пояснення редактору.</div></div><div class=\"final-note\">📌 Почесне авторство (honorary authorship) — коли шефу додають ім'я за статусом без реального внеску — порушення етики. Gift authorship і ghost authorship — прямі порушення за COPE (Committee on Publication Ethics). Не поступайся авторством під тиском.</div>"],[277,"Сильний фінал доповіді","<div class=\"rule-note\">🎯 <b>Фінал доповіді</b> — те, що залишається в пам'яті аудиторії. Слабкий фінал знецінює сильний виступ. Правило: ніколи не закінчуй «це все, що я хотів сказати» — це не фінал, це зупинка.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Три ефективних типи фіналу</b><br><b>Круговий фінал</b>: повертайся до вступного образу або питання — «На початку я запитав... Тепер ми знаємо, що...». <b>Call to action</b>: конкретна дія для аудиторії. <b>Перспектива</b>: «Якщо ця тенденція збережеться, через 5 років...» — відкриває думку, а не закриває.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Структура заключних 60 секунд</b><br>1) Сигнал завершення: «Підсумовуючи...» або «На завершення...». 2) Одне речення-суть: головний висновок без деталей. 3) Значення: чому це важливо. 4) Фінальна фраза: афористична, конкретна. Пауза після неї — не заповнюй тишу.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Чого уникати</b><br>«Дякую за увагу» — не фінал, а ввічливість; говори це після фінальної фрази. «Якщо є питання...» — не фінал. Вибачення за недоліки роботи — фінал не місце для цього. Нова інформація у фіналі — порушує структуру.</div></div><div class=\"final-note\">📌 Підготуй фінальну фразу дослівно і вивчи напам'ять. Решту можна імпровізувати — фінал ні. Репетируй лише з фінальною паузою: 2–3 секунди мовчання після останнього слова — це сила, не незручність.</div>"],[278,"Фасилітація групової роботи","<div class=\"rule-note\">👥 <b>Фасилітація</b> — управління груповим процесом для досягнення спільного результату. Фасилітатор не вирішує за групу — він допомагає групі вирішити самостійно.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Запуск групової сесії</b><br>Визнач мету: що конкретно має бути результатом? Правила роботи: один говорить — інші слухають; критика ідей, а не людей; кожна думка фіксується. Check-in: коротке слово від кожного учасника на початку — знімає мовчання на перших хвилинах.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Інструменти управління дискусією</b><br>Parking lot: фіксуй важливі але off-topic думки окремо — «Зафіксую це, повернемось пізніше». Dot voting: кожен ставить 3–5 точок біля пріоритетних ідей — швидкий консенсус без суперечок. Timeboxing: фіксований час на кожне питання — рухає вперед.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Складні ситуації</b><br>Один домінує: «Дякую, давайте почуємо інших». Мовчання групи: конкретне питання одному учаснику. Конфлікт: «Є дві позиції. Що потрібно, щоб кожна сторона почувалась почутою?» Відхід від теми: повертай до мети сесії.</div></div><div class=\"final-note\">📌 Результат фасилітації завжди фіксується письмово і розсилається учасникам до 24 год. Усна домовленість без протоколу — не домовленість. Інструменти для онлайн: Miro (стікери, голосування), Mentimeter (анонімне голосування).</div>"],[279,"Аналіз рецензій наукових журналів","<div class=\"rule-note\">📋 <b>Peer-review рецензія</b> — зворотний зв'язок від 2–3 анонімних експертів. Відхилення або запит на доопрацювання (major/minor revision) — норма, а не провал. Більшість публікацій у топ-журналах проходять мінімум одне доопрацювання.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Читання рецензії: перший крок</b><br>Прочитай повністю, не реагуй одразу. Зроби перерву 24–48 годин якщо реакція емоційна. Класифікуй зауваження: обов'язкові (major), бажані (minor), і ті що є думкою рецензента, а не вимогою. Не кожне зауваження потребує змін — потребує відповіді.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Структура Response to Reviewers</b><br>Лист-відповідь: подяка редактору і рецензентам. Далі по кожному зауваженню: цитата зауваження → твоя відповідь → зміни у рукописі (вказуй рядки або сторінки). Якщо не погоджуєшся: «We respectfully disagree because...» + аргументи і джерела.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Технічна робота з рукописом</b><br>Track Changes (Word) або diff (LaTeX) — показуй що саме змінено. Маркуй зміни кольором або коментарями що відповідають пунктам рецензії. Не роби змін понад запитані — це ускладнює перевірку редактором.</div></div><div class=\"final-note\">📌 Терміни: зазвичай 30–60 днів на major revision. Якщо потрібно більше — напиши редактору з поясненням, більшість журналів дають продовження. Reject with resubmit — не відмова: означає «доопрацюй суттєво і подай знову».</div>"],[280,"Самоконтроль перед виходом на трибуну","<div class=\"rule-note\">🧘 <b>Передвиступне хвилювання</b> — фізіологічна реакція: адреналін підвищує концентрацію і голос. Мета не усунути хвилювання, а направити його в корисне русло.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Фізична підготовка за 5 хвилин</b><br>Дихання 4-7-8: вдих 4 рахунки, затримка 7, видих 8 — знижує ЧСС. Поза сили (power pose) 2 хвилини: стоячи, руки на стегнах, підборіддя вгору — підвищує впевненість (дослідження Cuddy, Harvard). Кілька гучних видихів — скидає м'язове напруження.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Когнітивний рефреймінг</b><br>«Я хвилююсь» → «Я збуджений і готовий». Нейробіологічно це схожі стани — різниця лише в інтерпретації. Дослідження Brooks (2014, Harvard): учасники що говорили «I am excited» перед виступом показували кращі результати ніж ті що намагались заспокоїтись.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Технічна перевірка</b><br>За 10 хв до виступу: перевір мікрофон і слайди. Знай перші два речення напам'ять — коли починаєш впевнено, тривога спадає. Визнач де стоятимеш, куди дивитимешся в перші секунди. Вода поруч — пересихання в горлі норма.</div></div><div class=\"final-note\">📌 Довгострокове: хвилювання зменшується з кількістю виступів. Toastmasters, студентські конференції, семінарські заняття — будь-яка публічна практика рахується. Перші 30 секунд — найважчі: після них стає легше завжди.</div>"],[281,"Підготовка Handouts","<div class=\"rule-note\">📄 <b>Handout</b> — роздатковий матеріал для аудиторії: комісії, учасників конференції. Не копія слайдів, а самостійний документ з додатковою інформацією або деталями що не влізли в презентацію.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що включати у handout</b><br>Контактна інформація і дата. Ключові дані і таблиці — повні, не скорочені як на слайді. Список літератури: 5–10 ключових джерел. QR-код на повну версію роботи або репозиторій. Те що слухачі захочуть зберегти — не те що і так є на слайдах.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Формат для захисту диплому</b><br>1–2 сторінки A4, двосторонній друк. Шрифт: мінімум 11pt. Таблиці і рисунки чорно-білі (для друку). Нумеруй сторінки. Кількість примірників: кількість членів комісії + 2 запасних. Роздавай перед початком, а не під час виступу.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Handout для конференції</b><br>Формат A5 або складений A4 — легше носити. QR-код на препринт або слайди — основний інструмент. Контакт для follow-up: email або LinkedIn. Якщо постер — роздай QR-листівки замість повного handout.</div></div><div class=\"final-note\">📌 Не роздавай handout на початку довгого виступу — читатимуть замість слухати. Оптимально: під час Q&A або після. Цифровий варіант: завантаж на ResearchGate або Slideshare і дай посилання або QR.</div>"]]},{"n":"🚀 БЛОК 5: Професійний старт, кар'єра та сталість","e":"","cards":[[282,"Складання академічного CV","<div class=\"rule-note\">📄 <b>Академічне CV</b> (Curriculum Vitae) відрізняється від резюме: немає обмеження сторінок, містить всі публікації, конференції, гранти і викладацький досвід. Використовується для PhD-програм, постдоків, грантів.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Обов'язкові розділи</b><br>Контакт + ORCID. Education: від останнього вищого. Research interests: 3–5 ключових напрямів. Publications: APA або Vancouver стиль, з DOI. Conference presentations: де виступав. Grants & Awards. Teaching experience. References: 2–3 контакти з дозволу.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Публікації і препринти</b><br>Поділяй: peer-reviewed journals / conference proceedings / book chapters / preprints. Якщо публікацій немає — вкажи «in preparation» або «under review» з назвою. Не вигадуй і не прикрашай статус — перевіряється легко. Impact factor журналу можна вказати в дужках.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Оформлення і об'єм</b><br>Студент/аспірант: 1–3 сторінки. Досвідчений дослідник: стільки скільки треба. Шрифт: Times New Roman або Arial 11–12pt. Не вживай фото (у більшості країн Заходу — не прийнято). Оновлюй після кожної публікації або виступу.</div></div><div class=\"final-note\">📌 Для Erasmus+/PhD у ЄС: стандарт Europass CV (europass.europa.eu) — є шаблон. Для США/Канади: формат відрізняється, дізнайся вимоги конкретної програми. Завжди адаптуй CV під конкретну позицію — виноси вперед найрелевантніше.</div>"],[283,"Подача заявок на гранти (Erasmus+)","<div class=\"rule-note\">🎓 <b>Erasmus+</b> — програма ЄС для навчання, стажування і досліджень за кордоном. Фінансує переїзд, проживання і навчання. Подається через університет — не індивідуально.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Типи грантів Erasmus+ для студентів</b><br>KA131 (навчання в ЄС): обмін між університетами-партнерами, 3–12 місяців. KA131 (стажування): практика у компанії ЄС, 2–12 місяців. KA171 (з країнами поза ЄС): обмін з університетами-партнерами поза ЄС. Перший крок: International Office твого університету — вони знають партнерів і дедлайни.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Документи для заявки</b><br>Transcript of Records: оцінки, переведені в ECTS. Language certificate: зазвичай B2 мови навчання (тест OLS — безкоштовний для Erasmus). Motivation letter: чому саме цей університет і цей напрям. Learning Agreement: погоджений план навчання з обома університетами. CV (Europass).</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мотиваційний лист для Erasmus+</b><br>Параграф 1: конкретний дослідницький або навчальний інтерес. Параграф 2: чому саме цей університет (конкретні курси або лабораторії). Параграф 3: як це пов'язано з твоїми цілями. Параграф 4: що даси програмі і університету. Уникай загальних фраз — комісія читає сотні заявок.</div></div><div class=\"final-note\">📌 Дедлайни: зазвичай лютий–березень для осіннього семестру; вересень–жовтень для весняного. Дізнайся в International Office — дедлайни у кожному університеті різні. Гранти не покривають 100% витрат — рахуй реальний бюджет.</div>"],[284,"Професійний профіль у LinkedIn / ResearchGate","<div class=\"rule-note\">🌐 <b>Онлайн-профіль дослідника</b> — твоя видимість для рекрутерів, колег і грантодавців. ResearchGate — для академічного нетворкінгу і розповсюдження публікацій. LinkedIn — для зв'язків з індустрією і нон-академічними роботодавцями.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>LinkedIn: що обов'язково</b><br>Фото: profesійне, нейтральний фон. Headline: не «Студент», а «Researcher in [field] | [University]». About: 3–5 речень про інтереси і досягнення. Experience: наукова робота, стажування, RA позиції. Skills: 10–15 навичок з підтвердженнями. Публікації: додай через розділ Publications.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>ResearchGate: налаштування профілю</b><br>Завантаж всі публікації (або препринти де немає відкритого доступу). Заповни Research interests — впливає на рекомендації і знаходження. Відповідай на Questions у своїй темі — підвищує RG Score. Слідкуй за авторами у своїй галузі — алерти на нові публікації.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>ORCID і Google Scholar</b><br>ORCID iD: зареєструйся на orcid.org — унікальний ідентифікатор, пов'язуй з усіма публікаціями. Google Scholar: після першої публікації — створи профіль (scholar.google.com), додай фото і інтереси — автоматично відстежує цитування.Ці два профілі — основа академічної ідентичності.</div></div><div class=\"final-note\">📌 Активність важливіша за заповненість: коментуй роботи колег, ділись новинами галузі, пиши про свої дослідження простою мовою. Алгоритм LinkedIn підвищує видимість активних профілів. Раз на квартал: оновити досягнення і перевірити актуальність.</div>"],[285,"Мотиваційний лист (Statement of Purpose)","<div class=\"rule-note\">✍️ <b>Statement of Purpose (SOP)</b> — найважливіший документ вступу до магістратури або PhD. Комісія вирішує чи відповідаєш ти програмі і чи відповідає програма тобі. Загальні фрази — головна помилка.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура SOP (1–2 сторінки)</b><br>Параграф 1 — гачок: конкретний момент або дослідження що визначило інтерес. Параграф 2–3 — твій досвід: конкретні проєкти, методи, результати. Параграф 4 — чому ця програма: конкретні курси, лабораторії, викладачі. Параграф 5 — цілі: що плануєш робити після.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Персоналізація під програму</b><br>Дізнайся дослідницькі інтереси 2–3 викладачів програми → згадай конкретно: «Дослідження Prof. X щодо Y суголосне з моєю роботою з...». Це показує що ти дійсно дослідив програму, а не розсилаєш один і той самий лист. Кожен SOP — унікальний.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Мова і тон</b><br>Конкретно: «Я проаналізував 500 зразків методом PCR» замість «Я маю досвід у лабораторній роботі». Активний стан: «Я розробив», «Я виявив». Без надмірної скромності і без хвалькуватості. Довжина: зазвичай 500–1000 слів — дотримуйся обмежень програми.</div></div><div class=\"final-note\">📌 Попроси 2–3 людей прочитати: наукового керівника, колегу з іншого напряму (чи зрозуміло неспеціалісту?), носія мови якщо англійська. Почни писати за місяць до дедлайну — потрібно кілька редакцій. Перша версія завжди погана — це нормально.</div>"],[286,"Баланс між роботою та навчанням","<div class=\"rule-note\">⚖️ <b>Поєднання роботи і навчання</b> — системна задача, а не питання сили волі. Без структури один з напрямів неминуче деградує. Мета: зробити обидва передбачуваними, а не реагувати на кожен дедлайн.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Аудит часу як перший крок</b><br>Протягом тижня фіксуй кожен часовий блок по 30 хвилин: що реально робив. Більшість людей не знають куди іде час. Без цього планування — здогадки. Інструменти: Toggl Track (безкоштовно), таблиця в Google Sheets, або просто нотатки.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Часові блоки замість списків задач</b><br>Розклад з фіксованими блоками: «Пн-Ср-Пт 7:00–9:00 — навчання», «Вт-Чт 19:00–21:00 — навчання». Робота і навчання — окремі блоки, не перемішуються. Дедлайни вносяться у календар зворотньо: коли треба починати щоб встигнути?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Комунікація з роботодавцем і університетом</b><br>Роботодавцю — чесно про сесію і великі дедлайни: більшість розуміють якщо попередити заздалегідь, а не в день здачі. Університету — щодо можливості дистанційного складання або індивідуального графіку: офіційно оформлена робота може давати право на пільги.</div></div><div class=\"final-note\">📌 Енергія важливіша за час: 2 години відпочилого мозку = 4 години втомленого. Захищай сон (7–8 годин) навіть у сесію — когнітивні функції деградують швидше ніж здається. Одна «нічна зміна» може збивати ритм на 3–4 дні.</div>"],[287,"Формування портфоліо проєктів","<div class=\"rule-note\">💼 <b>Портфоліо</b> — підбірка реальних робіт що демонструють навички. Для технічних і творчих спеціальностей часто важливіше за диплом. Показуй що вмієш — не розповідай.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Що включати</b><br>3–5 кращих проєктів, а не все що є. Критерії вибору: різноманітність навичок, реальні результати (не лише навчальні), проблема → рішення → результат. Для кожного проєкту: контекст, твоя роль, що конкретно зробив, результат (число, відгук, впровадження).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>GitHub як технічне портфоліо</b><br>Профільний README: коротко хто ти і що вмієш. Репозиторії: зрозумілий README кожного проєкту (що це, як запустити, приклади). Commits — регулярні і з описами: показує реальну роботу, а не готовий код. Pinned repositories: 4–6 найкращих проєктів зверху.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Портфоліо-сайт або PDF</b><br>Notion, GitHub Pages або Webflow — безкоштовні варіанти для простого сайту. Структура: хто я + навички → проєкти (кожен з описом і посиланням) → контакт. PDF-версія для email: 1–2 сторінки, найкращі 3 проєкти, посилання на повну версію.</div></div><div class=\"final-note\">📌 Навчальні проєкти теж підходять якщо показують реальні навички. Вкажи: «Дипломна робота: розробив X, що вирішує Y». Регулярно оновлюй: застарілі проєкти без поновлення говорять що ти не розвиваєшся.</div>"],[288,"Підготовка до технічного інтерв'ю","<div class=\"rule-note\">💻 <b>Технічне інтерв'ю</b> — структурована перевірка компетентностей. Більшість компаній використовують: кейс-задачі, live coding, або системне проєктування. Підготовка за 2–4 тижні значно підвищує результат.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Алгоритмічні задачі (для IT)</b><br>LeetCode, HackerRank: починай з Easy, переходь до Medium. Пріоритетні теми: масиви і рядки, хеш-таблиці, стек/черга, бінарний пошук, граф (BFS/DFS), динамічне програмування. Розв'язуй вголос — інтерв'юер оцінює хід думок, не лише відповідь.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Кейс-інтерв'ю (для бізнес-спеціальностей)</b><br>Структура відповіді: уточни питання → визнач структуру аналізу → йди послідовно. MECE-принцип: Mutually Exclusive, Collectively Exhaustive — розбивай проблему без перекриттів і прогалин. Практикуй з партнером: McKinsey, BCG, Case In Point — стандартні ресурси.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Поведінкові питання (STAR-метод)</b><br>Situation, Task, Action, Result. «Розкажіть про складний проєкт» → конкретна ситуація → що треба було зробити → що конкретно ти зробив → який результат. Підготуй 4–5 таких прикладів з реального досвіду.</div></div><div class=\"final-note\">📌 Mock interviews: Pramp, interviewing.io — безкоштовні сервіси для практики з реальними людьми. Дізнайся формат конкретної компанії — він суттєво різниться. Запитай рекрутера: «Яка структура технічного інтерв'ю?» — це нормальне питання.</div>"],[289,"Управління проєктами за Agile / Kanban","<div class=\"rule-note\">📋 <b>Agile і Kanban</b> — підходи до управління роботою орієнтовані на гнучкість і видимість прогресу. Kanban — візуальна система управління потоком задач. Застосовується не лише в IT: підходить для будь-якого проєкту з багатьма задачами.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Kanban-дошка: базова структура</b><br>Мінімум 3 колонки: To Do → In Progress → Done. Правило WIP-ліміту: максимальна кількість задач в In Progress (зазвичай 2–3) — запобігає перевантаженню і підвищує фокус. Задача рухається лише вперед. Завершена задача — видима перемога.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Trello для особистого використання</b><br>Безкоштовний. Дошка = проєкт. Картка = задача. Мітки для пріоритетів (червоний/жовтий/зелений). Дедлайни на картках — нагадування у вбудованому календарі. Power-Up «Calendar» показує всі дедлайни по датах. Trello достатньо для команди до 10 осіб.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Scrum для командної роботи</b><br>Sprint: фіксований цикл роботи 1–2 тижні з конкретним результатом. Daily standup: 15 хвилин — що зробив вчора, що робиш сьогодні, що блокує. Retrospective наприкінці: що добре, що покращити, що змінити. Jira — стандарт для Scrum в IT-командах.</div></div><div class=\"final-note\">📌 Для студентських проєктів: Trello або Notion достатньо. Jira — коли команда вже знайома з Agile і потрібна звітність. Головне правило Kanban: роби менше одночасно — швидше завершуєш кожну задачу.</div>"],[290,"Профілактика академічного вигорання","<div class=\"rule-note\">🔥 <b>Академічне вигорання</b> — стан хронічного виснаження від навчального навантаження. Характеристики: цинізм щодо навчання, зниження ефективності, відчуття безглуздості. Відрізняється від втоми: відпочинок не відновлює.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Ранні сигнали</b><br>Прокрастинація завдань які раніше давались легко. Відчуття що «не встигаю» навіть при малому навантаженні. Дратівливість, складнощі з концентрацією. Порушення сну. Ці сигнали — привід змінити щось зараз, а не чекати поки стане гірше.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Структурні причини і рішення</b><br>Надлишок зобов'язань: навчись говорити «ні» новим задачам коли поточні незавершені. Відсутність відновлення: заплановані паузи — не розкіш, а умова ефективності. Відсутність прогресу: розбивай великі задачі на малі з видимим результатом кожного дня.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Відновлення під час диплому</b><br>Мінімальний рухливий відпочинок щодня: 20–30 хвилин прогулянки знижує кортизол. Соціальний контакт: повна ізоляція заради диплому погіршує когнітивні функції. Техніка Pomodoro: 25 хвилин роботи + 5 хвилин відпочинку — структурує час і обмежує перевантаження.</div></div><div class=\"final-note\">📌 Якщо стан не покращується 2+ тижні: звернись до психолога університету (більшість університетів мають безкоштовну службу) або до психотерапевта. Вигорання — медичний стан, а не слабкість характеру. Своєчасна допомога скорочує відновлення.</div>"],[291,"Комерціалізація наукових ідей","<div class=\"rule-note\">💡 <b>Комерціалізація</b> — перетворення результату дослідження на продукт або послугу. Більшість університетів мають відділ трансферу технологій (ТТО) — перший крок саме туди.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Оцінка комерційного потенціалу</b><br>Питання до ідеї: хто буде платити і за що? Яка проблема вирішується і наскільки вона болюча? Чи є вже рішення і чим твоє краще? Яким шляхом доставиш продукт до клієнта? Відповіді до початку будь-якої комерціалізації — не після.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Захист IP до розкриття</b><br>Перед розмовою з потенційним партнером або інвестором: пріоритетна патентна заявка (utility patent application) встановлює дату пріоритету без повного розкриття. Авторське свідоцтво на програмний код — реєструється в УКРПАТЕНТ. NDA з партнерами — мінімальний захист для непатентованого.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Шляхи комерціалізації</b><br>Ліцензування: продаєш право використання — найпростіший шлях. Спін-офф / стартап: створюєш компанію навколо технології. Контрактні дослідження: компанія платить за прикладне дослідження під конкретну задачу. НФДУ, МОН, EU Horizon — грантові програми для R&D стадії.</div></div><div class=\"final-note\">📌 Угода з університетом: в більшості університетів IP що створено під час навчання або з використанням ресурсів університету — частково або повністю належить університету. Уточни умови в ТТО до початку комерціалізації.</div>"],[292,"Пошук ментора чи керівника PhD","<div class=\"rule-note\">🎓 <b>Науковий керівник PhD</b> — найважливіше рішення у докторській програмі. Відносини на 3–5 років визначають якість дослідження і кар'єрні перспективи. Вибір керівника = вибір середовища.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Де і як шукати</b><br>Google Scholar: пошук за ключовими словами твоєї теми → автори з цитованими роботами → перевір їх профіль. ResearchGate, сайти університетів. Конференції: познайомся особисто — найефективніший шлях. Запитай свого наукового керівника про колег у галузі.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Оцінка потенційного керівника</b><br>Перевір: скільки PhD студентів успішно захистилось? Яка середня тривалість докторантури в групі? Чи публікуються студенти (не лише керівник)? Поговори з поточними або колишніми студентами — найчесніше джерело. Стиль керівництва: автономія vs мікроменеджмент?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перший контакт</b><br>Email: персоналізований (конкретна стаття), коротко твій досвід, конкретна ідея проєкту, CV і 1 сторінка research proposal. Якщо немає відповіді через тиждень — один follow-up. Зустріч: підготуй питання про дослідницькі напрями, очікування від PhD студента, фінансування.</div></div><div class=\"final-note\">📌 Червоні прапорці: «Всі мої студенти беруть більше 5 років», «Я дуже зайнятий зараз», відсутність відповідей на email від поточних студентів. Хороший знак: публікації у співавторстві зі студентами, студенти що захищаються і знаходять роботу.</div>"],[293,"Захист інтелектуальної власності","<div class=\"rule-note\">⚖️ <b>Інтелектуальна власність (ІВ)</b> — право на результати творчої або інтелектуальної діяльності. В Україні регулюється ЦКУ (кн. 4) і спеціальними законами. Захист починається з фіксації факту створення.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Авторське право</b><br>Виникає автоматично з моменту створення — реєстрація не обов'язкова, але бажана для суперечок. УКРПАТЕНТ: реєстрація авторського права на твір (код, текст, дизайн). Вартість: фіксована держмито. Дає: офіційне підтвердження дати і авторства. Для програмного коду — основний інструмент захисту.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Патент на винахід</b><br>Умови патентоздатності: новизна, винахідницький рівень, промислова застосовність. Строки: пріоритетна заявка → публікація через 18 міс → видача патенту (~2–3 роки). Корисна модель («малий патент»): швидше (12 міс), без перевірки рівня — для технічних рішень. УКРПАТЕНТ — укрпатент.gov.ua.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Торговельна марка і комерційна таємниця</b><br>Торговельна марка: захищає назву і лого — реєстрація в УКРПАТЕНТ. Комерційна таємниця: NDA з усіма хто має доступ, контроль доступу до документів. Іноді вигідніше ніж патент: патент розкриває технологію, таємниця — ні (але не захищає від паралельного відкриття).</div></div><div class=\"final-note\">📌 Міжнародний захист: PCT-заявка через ВОІВ — захист у 150+ країнах одночасно. Дорого, але єдиний шлях для глобального ринку. Перший крок завжди: консультація з патентним повіреним — УКРПАТЕНТ публікує реєстр.</div>"],[294,"Адаптація на виробничій практиці","<div class=\"rule-note\">🏭 <b>Виробнича практика</b> — перший реальний робочий досвід. Перші 2 тижні: ти нічого не знаєш про внутрішні процеси конкретного місця — і це нормально. Задача: швидко зрозуміти контекст, показати надійність.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Перший тиждень: спостерігай і питай</b><br>Не пропонуй «покращення» одразу — ти не знаєш чому все влаштовано саме так. Завдання першого тижня: зрозуміти хто що робить, як приймаються рішення, хто неформальний лідер. Питання до наставника: «Яка головна пріоритетність моїх задач?», «Як ти хочеш отримувати оновлення?»</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Показати надійність</b><br>Дедлайни: виконуй або попереджай заздалегідь. Якщо не знаєш — питай одразу, а не через два дні. Дрібні задачі: виконуй бездоганно — на них тебе оцінюють першими. Записуй що робиш — для звіту і для пам'яті.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Максимізація користі від практики</b><br>Знайди одну реальну проблему підприємства і запропонуй рішення на основі своїх знань. Це матеріал для дипломної і демонстрація ініціативи. Попроси зворотній зв'язок в кінці практики — пряме питання наставнику: «Що я міг зробити краще?»</div></div><div class=\"final-note\">📌 Звіт з практики: пиши по ходу, не в останній день. Фіксуй конкретні задачі, що робив, що навчився — загальні фрази у звіті не зараховуються. Рекомендаційний лист від наставника: попроси за 1–2 тижні до кінця практики, а не в останній день.</div>"],[295,"План професійного розвитку (IDP)","<div class=\"rule-note\">🗺️ <b>Individual Development Plan (IDP)</b> — документ з цілями кар'єрного розвитку, навичками для набуття і конкретними кроками. Використовується в академії (аспіранти) і корпоративному секторі. Без плану — розвиток хаотичний.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Структура IDP</b><br>1) Довгострокова мета (3–5 років): де хочу бути? 2) Поточний стан: які навички є і на якому рівні? 3) Gap-аналіз: що потрібно для досягнення мети? 4) Конкретні кроки на рік: курси, проєкти, стажування, публікації. 5) Критерії успіху: як пойму що досяг?</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Навички vs Результати</b><br>Неправильно: «Покращити навички аналізу даних». Правильно: «До грудня завершити курс SQL на Coursera і застосувати в дипломній роботі». Кожен пункт: конкретна дія + дедлайн + що доводить виконання. Навичка без застосування — не навичка.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перегляд і коригування</b><br>IDP — живий документ, не присяга. Переглядай щоквартально: що виконано, що змінилось у цілях, що блокує. Обговорюй з ментором або науковим керівником — зовнішній погляд виявляє сліпі зони. Невиконані пункти: аналізуй причину і перепланируй, а не переноси механічно.</div></div><div class=\"final-note\">📌 Інструменти: MyIDP (science careers, для науковців) — безкоштовний онлайн-сервіс для IDP. Notion, Google Docs або навіть таблиця — підходить будь-що що ти реально використовуєш.</div>"],[296,"Запит рекомендаційних листів","<div class=\"rule-note\">📩 <b>Рекомендаційний лист</b> — документ від людини що знає тебе в академічному або професійному контексті. Для PhD, магістратури, грантів — зазвичай потрібно 2–3. Якість важливіша за статус підписанта.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Кого просити</b><br>Той хто знає тебе в контексті роботи: науковий керівник, викладач курсу де ти справді працював, наставник практики. Не проси: людину що знає тебе лише як студента у потоці 200 осіб — лист буде загальним і слабким. «Він хороший студент» — не рекомендація.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Як правильно просити</b><br>За 4–6 тижнів до дедлайну — не за 3 дні. Особисто або email: поясни навіщо подаєш і чому просиш саме їх. Дай матеріали: CV, SOP, опис програми/позиції, конкретні проєкти/роботи де ви співпрацювали. Запитай: «Чи зможете написати сильну рекомендацію?» — якщо вагаються, краще знайти іншого.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Після отримання листа</b><br>Подякуй після подачі — email достатньо. Повідом про результат: прийнятий або ні — рекомендатор зазвичай цікавиться. Якщо цього ж рекомендатора плануєш просити знову — зберігай стосунки, не зникай після отримання листа.</div></div><div class=\"final-note\">📌 Деякі програми надсилають запит безпосередньо рекомендатору — уточни формат: потрібно завантажити PDF чи є форма онлайн? Дай рекомендатору всі технічні деталі — посилання, дедлайн, інструкції — щоб мінімізувати їхній адміністративний клопіт.</div>"],[297,"Подолання синдрому самозванця на роботі","<div class=\"rule-note\">🧠 <b>Синдром самозванця</b> — переконання що твої успіхи випадкові, а некомпетентність скоро буде розкрита. Поширений серед студентів і початківців. Не психічний розлад — когнітивний патерн.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Звідки береться</b><br>Порівняння свого внутрішнього (сумніви, невпевненість) з зовнішнім фасадом інших (впевненість, досягнення). Новий контекст: коли опиняєшся серед досвідченіших — відчуття «я не доріс» норма на початку. Перфекціонізм підсилює: будь-яка помилка = підтвердження «я самозванець».</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Практичні протидії</b><br>Список досягнень: фіксуй що зробив добре — мозок природньо зосереджується на невдачах. Порівнюй з собою минулим, а не з кращими іншими. Normalize failure: помилки роблять всі — різниця у тому як реагують. Запитай колегу — зазвичай виявляється що вони теж сумніваються.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Перехід від студента до спеціаліста</b><br>Студент: оцінюється за знання. Спеціаліст: оцінюється за рішення і результат. Перший рік — зміна парадигми: «не знати» нормально, «не запитувати» — ні. Компетентність будується через практику, а не через читання — дій, отримуй зворотний зв'язок, коригуй.</div></div><div class=\"final-note\">📌 Якщо стан хронічний і впливає на роботу і відносини — це варто обговорити з психологом. Синдром самозванця корелює з тривожністю і перфекціонізмом, що добре піддаються КПТ (когнітивно-поведінковій терапії).</div>"],[298,"Аналіз ринку праці","<div class=\"rule-note\">📊 <b>Аналіз ринку праці</b> — систематичний збір даних про попит на навички, рівні зарплат і тренди у своїй галузі. Без цього кар'єрні рішення приймаються інтуїтивно.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Де дивитись попит на навички</b><br>Аналізуй 30–50 вакансій у своїй галузі: які навички зустрічаються в кожній? Що написано в «Обов'язково» vs «Буде перевагою»? Це реальний список що треба розвивати. LinkedIn Jobs, Work.ua, Djinni (IT) — основні майданчики в Україні.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Дані про зарплати</b><br>Djinni (IT сектор): відкрита статистика зарплат за технологіями і рівнями. DOU.ua: щорічні опитування зарплат в IT. Work.ua і Rabota.ua: менш точні — компанії часто не вказують. Glassdoor і Levels.fyi — для міжнародного ринку. Уточнюй: це gross (до вирахування) чи net?</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Трендові навички vs базові</b><br>Базові (завжди потрібні): комунікація, аналітичне мислення, профільні технічні навички. Трендові (зростає попит): AI/ML tools, data literacy, конкретні технології галузі. Перевіряй тренди через: Google Trends, LinkedIn Skills Insights, галузеві звіти (McKinsey, WEF Future of Jobs).</div></div><div class=\"final-note\">📌 Оновлюй аналіз раз на рік — ринок праці змінюється швидко. Інформаційні інтерв'ю: 20-хвилинна розмова з практиком у своїй галузі дає більше ніж 10 годин читання — питай через LinkedIn.</div>"],[299,"Участь у хакатонах та кейс-чемпіонатах","<div class=\"rule-note\">🏆 <b>Хакатон</b> — інтенсивне командне змагання (24–72 год) зі створення прототипу або рішення. Кейс-чемпіонат — вирішення бізнес-задачі і презентація перед журі. Обидва: реальний досвід + нетворкінг + портфоліо.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Як готуватись до хакатону</b><br>Команда з комплементарними навичками: розробник + дизайнер + продукт/комунікації. Перед подією: вивчи організатора і тему — часто тему оголошують завчасно. Технічний стек вибирай знайомий, а не найкращий теоретично — часу немає вчитися на ходу.</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Структура роботи під час хакатону</b><br>Перші 2 години: ідея → бачення рішення → розподіл задач. Не витрачай перші 4 години на планування. MVP (мінімальний прототип) що демонструє ідею — ціль. Питай менторів: більшість хакатонів мають менторів від спонсорів — використовуй.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Презентація рішення (pitch)</b><br>5 хвилин: проблема (30 сек) → рішення (1 хв) → демо (2 хв) → бізнес-модель (1 хв) → команда (30 сек). Демо важливіше за слайди: покажи що працює, навіть якщо це mockup. Антипитання від журі: «Чому це краще ніж X?» — підготуй відповідь.</div></div><div class=\"final-note\">📌 Пошук хакатонів: Devpost, mlh.io, Hackathon.com, Facebook-групи «хакатон Україна». Призи часто символічні — головна цінність: досвід, портфоліо і знайомства. Навіть без призового місця — участь варта.</div>"],[300,"Організація Work-Life Balance","<div class=\"rule-note\">⚖️ <b>Work-Life Balance</b> — не рівний поділ часу 50/50, а відчуття що кожна сфера отримує достатньо уваги. У різні періоди балans зміщується — важливо вміти це помічати і коригувати.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Межі між роботою і відпочинком</b><br>Фізична межа: окреме місце для роботи якщо вдома — мозок починає асоціювати простір. Часова межа: фіксований час завершення роботи — «я закінчую о 19:00» і дотримуйся. Технологічна межа: робочі повідомлення — не у вихідні (або визначений «тихий час»).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Пріоритизація сфер</b><br>Запитай себе: які 3 сфери найважливіші зараз (кар'єра, здоров'я, відносини, хобі, навчання)? Вклади час туди в першу чергу. «Так» для чогось = «ні» для чогось іншого. Переглядай пріоритети щоквартально — вони змінюються з обставинами.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Відновлення: що реально працює</b><br>Активний відпочинок (рух, природа, соціальний контакт) відновлює краще ніж пасивний (серіали, соцмережі) за дослідженнями відновлення. Щоденний мінімум: щось приємне кожен день — навіть 20 хвилин. Відпустка: повне відключення від роботи — потрібно планувати як проєкт.</div></div><div class=\"final-note\">📌 Немає універсальної формули: хтось продуктивний увечері, хтось вранці; хтось потребує повного вихідного, хтось — годину щодня. Відстежуй свій стан і адаптуй систему під себе, а не під чужі поради.</div>"],[301,"Концепція Lifelong Learning","<div class=\"rule-note\">📚 <b>Lifelong Learning</b> — безперервне навчання протягом усього життя. Не факультатив, а необхідність: за оцінками WEF, половина поточних навичок застаріє протягом 5 років. Система самонавчання важливіша ніж конкретний курс.</div><div class=\"step c1\"><div class=\"step-num\">1</div><div class=\"step-text\"><b>Побудова системи самонавчання</b><br>Навчальний бюджет часу: фіксований блок щотижня — наприклад 3–5 годин. Не «коли буде час» — не буде. Баланс: 70% навчання через практику і реальні задачі, 20% через взаємодію з іншими, 10% через курси і книги (модель 70-20-10).</div></div><div class=\"step c2\"><div class=\"step-num\">2</div><div class=\"step-text\"><b>Ресурси для безперервного навчання</b><br>Coursera, edX: курси університетів, є безкоштовний аудит. MIT OpenCourseWare: повні матеріали курсів MIT безкоштовно. YouTube-канали у своїй галузі: практичне навчання. Наукові журнали (відкритий доступ): DOAJ, PubMed Central, arXiv. Книги: 12 нон-фікшн книг на рік = 1 на місяць — реалістично.</div></div><div class=\"step c3\"><div class=\"step-num\">3</div><div class=\"step-text\"><b>Як навчатись ефективно</b><br>Retrieval practice: тести себе замість перечитування — ефективніший метод запам'ятовування за даними когнітивної психології. Spaced repetition: Anki для запам'ятовування фактів і термінів. Навчи когось: пояснення іншому виявляє прогалини у розумінні (метод Фейнмана). Застосовуй одразу — знання без практики не закріплюється.</div></div><div class=\"final-note\">📌 Небезпека: «курсова залежність» — постійне проходження курсів без реального застосування. Критерій ефективного навчання: чи змінилась твоя поведінка або результати? Якщо ні — зміни підхід, а не збільшуй кількість курсів.</div>"]]}]};
if(window.__catLoaded)window.__catLoaded(3,CAT_3);